function renderLanguageSwitcher() {
  const wrap = document.getElementById("langSwitcherWrap");
  if (!wrap) return;
  const opts = languageList().map((l) => [l.code, l.name + (l.hidden ? " (hidden)" : "")]);
  const code = document.getElementById("langBtnCode");
  if (code) code.textContent = String(LANG || "en").split("-")[0].toUpperCase();
  const lb = document.getElementById("langBtn");
  if (lb) lb.title = t("language");
  wrap.innerHTML = `
    <div class="meta" style="font-size:11px; margin:2px 4px 6px; text-transform:uppercase; letter-spacing:.6px;">${esc(t("language"))}</div>
    <div class="tn-lang-list">${opts.map(([c, label]) => `<button type="button" data-setlang="${esc(c)}" class="${c === LANG ? "on" : ""}"><span>${esc(label)}</span>${c === LANG ? "&#10003;" : ""}</button>`).join("")}</div>
  `;
  wrap.querySelectorAll("[data-setlang]").forEach((b) => b.addEventListener("click", () => { closeAllTopnavDropdowns(); if (b.dataset.setlang !== LANG) setLanguage(b.dataset.setlang); }));
}
async function setLanguage(lang) {
  lang = await useLanguage(lang);
  LANG = lang;
  localStorage.setItem("lang", lang);
  document.documentElement.dir = langDir(lang);
  document.documentElement.lang = lang;
  if (typeof applyMenuLayout === "function") applyMenuLayout();
  applyNavLanguage();
  renderLanguageSwitcher();
  renderOwnerLoginUI();
  render();
  localizeDom(document.body);
  syncAccountLang();
}

const KNOWN_TABS = new Set([
  "overview", "statetimeline", "budgets", "bestupgrades", "backpack", "packs", "mypacks", "purchases", "packcalendar", "charmscalc", "chiefgear",
  "herogearcalc", "skingallery", "islandgallery", "facilitypage", "t12research",
  "t11helios", "researchcenter", "rfclab", "petsdata", "refinepage", "expertspage",
  "expertsresearchpage", "adminpage", "alliancetechpage", "albumtundrapage",
  "collectiongallerypage", "extrabonusheroes", "contactpage", "aboutpage",
]);
function isValidTab(t) {
  return KNOWN_TABS.has(t) || (typeof t === "string" && (t.startsWith("extrabonus:") || t.startsWith("buffcat:")));
}
// A saved "roadmap" / "cando" (the old Roadmap / Can do pages) opens Budgets.
const SAVED_TAB = ["roadmap", "cando"].includes(localStorage.getItem("last_tab")) ? "budgets" : localStorage.getItem("last_tab");
let TAB = isValidTab(SAVED_TAB) ? SAVED_TAB : "overview";
// Phones may reload a page left in the background (switching apps). The page
// is reopened on the same tab (last_tab); this also keeps where it was
// scrolled and the My Purchases form.
(() => {
  const keep = () => {
    try {
      // Packs: the open editors and the pack at the top of the screen come back
      // too (after switching to the game and back the open
      // pack was closed and the page sat at the top).
      let anchor = null;
      if (TAB === "packs") {
        const card = [...document.querySelectorAll("[data-pkrowid]")].find((el) => el.getBoundingClientRect().bottom > 60);
        if (card) anchor = { id: card.dataset.pkrowid, off: Math.round(card.getBoundingClientRect().top) };
        if (typeof PACKS_OPEN !== "undefined") sessionStorage.setItem("packs_open", JSON.stringify([...PACKS_OPEN]));
      }
      sessionStorage.setItem("scroll_pos", JSON.stringify({ tab: TAB, y: Math.round(window.scrollY), anchor }));
      if (typeof PUR_FORM !== "undefined") sessionStorage.setItem("pur_form", JSON.stringify(PUR_FORM));
    } catch (e) { /* blocked */ }
  };
  document.addEventListener("visibilitychange", () => { if (document.visibilityState === "hidden") keep(); });
  window.addEventListener("pagehide", keep);
  let sp = null;
  try { sp = JSON.parse(sessionStorage.getItem("scroll_pos") || "null"); sessionStorage.removeItem("scroll_pos"); } catch (e) { sp = null; }
  if (!sp || sp.tab !== TAB || !(sp.y > 0)) return;
  // Wait until the page is drawn tall enough (up to 10 s), unless the person scrolls or changes page first.
  let tries = 0, moved = false;
  const stop = () => { moved = true; };
  window.addEventListener("touchstart", stop, { once: true, passive: true });
  window.addEventListener("wheel", stop, { once: true, passive: true });
  const iv = setInterval(() => {
    if (moved || TAB !== sp.tab || ++tries > 40) { clearInterval(iv); return; }
    if (sp.anchor) {
      const card = [...document.querySelectorAll("[data-pkrowid]")].find((el) => el.dataset.pkrowid === sp.anchor.id);
      if (card) { clearInterval(iv); window.scrollTo(0, window.scrollY + card.getBoundingClientRect().top - sp.anchor.off); }
      return;
    }
    if (document.documentElement.scrollHeight >= sp.y + innerHeight * 0.6) { clearInterval(iv); window.scrollTo(0, sp.y); }
  }, 250);
})();
// Browser history: every page change is a history entry, so the Back
