// One card: its label, then each block (a later block may have its own small heading).
function mmCardHtml(card) {
  const blocks = card.blocks.filter((b) => b.items.length);
  if (!blocks.length) return "";
  return `
      <div class="mm-hc" data-group="${esc(card.key)}">
        <div class="mm-hh"><span>${esc(card.label)}</span></div>
        ${blocks.map((b, i) => `${i && b.sub ? `<div class="mm-hh mm-hs"><span>${esc(b.sub)}</span></div>` : ""}${mmRowsHtml(b.items)}`).join("")}
      </div>`;
}
function mmVisibleGroups() {
  return [...topnavGroups.querySelectorAll(".topnav-group")].filter((g) => g.style.display !== "none");
}
function mmGroupBtns(g) {
  return [...g.querySelectorAll(".topnav-dropdown > button[data-tab]")];
}
// The Menu's cards from the real menu (#topnavGroups: Admin renames, moved pages and
// pages hidden for visitors follow): Overview (+ Planning: Marketplace, Budgets,
// My Purchases), Gears (+ the Experts and Pets tiles), then the other groups as they are.
function mmModel() {
  const groups = mmVisibleGroups();
  const byName = {};
  groups.forEach((g) => { byName[g.dataset.group] = g; });
  const vis = (g) => (g ? mmGroupBtns(g).filter((b) => b.style.display !== "none") : []);
  const all = groups.filter((g) => g.dataset.group !== "Admin").flatMap(vis);
  const pairTabs = new Set(MM_PAIRS.flatMap((p) => p.tabs));
  const lbl = (name, fb) => (byName[name] ? mmGroupLabel(byName[name]) : fb);
  const pi = {};
  for (const p of MM_PAIRS) {
    const btns = p.tabs.map((tb) => all.find((b) => b.dataset.tab === tb)).filter(Boolean);
    pi[p.key] = !btns.length ? null : btns.length === 1 ? { btn: btns[0] } : { pair: p, btns, label: p.label ? p.label() : lbl(p.group, mmBtnName(btns[0])) };
  }
  const own = (name) => vis(byName[name]).filter((b) => !pairTabs.has(b.dataset.tab)).map((btn) => ({ btn }));
  const done = new Set(["Overview", "Marketplace", "Planning", "Gears", "Experts", "Pets", "Admin"]);
  const cards = [
    { key: "Overview", label: lbl("Overview", "Overview"), blocks: [{ items: own("Overview") }, { sub: lbl("Planning", "Planning"), items: [pi.market, ...own("Marketplace"), ...own("Planning")].filter(Boolean) }] },
    { key: "Gears", label: lbl("Gears", "Gears"), blocks: [{ items: [...own("Gears"), pi.experts, pi.pets, ...own("Experts"), ...own("Pets")].filter(Boolean) }] },
  ];
  for (const g of groups) if (!done.has(g.dataset.group)) cards.push({ key: g.dataset.group, label: mmGroupLabel(g), blocks: [{ items: own(g.dataset.group) }] });
  return cards;
}
function mmCardTabs(card) {
  return card.blocks.flatMap((b) => b.items.flatMap((x) => (x.btn ? [x.btn.dataset.tab] : x.btns.map((b2) => b2.dataset.tab))));
}
function renderMobileMenu() {
  const overlay = document.getElementById("mobileMenuOverlay");
  // Admin = a "⚙ Admin" button in the Menu header, not a card.
  const admG = mmVisibleGroups().find((g) => g.dataset.group === "Admin");
  const admBtn = admG && mmGroupBtns(admG).find((b) => b.dataset.tab === "adminpage");
  const cards = mmModel().map(mmCardHtml).join("");
  overlay.innerHTML = `
    <div class="mm-header">
      <h2>${esc(t("menu_title"))}</h2>
      ${admBtn ? `<button type="button" class="mm-adm${TAB === "adminpage" ? " on" : ""}" data-mmadmin>&#9881; ${esc(navLabel("adminpage"))}</button>` : ""}
      <button class="mm-close" type="button" id="mmCloseBtn" aria-label="${esc(t("mm_close"))}" title="${esc(t("mm_close"))}">&#10005;</button>
    </div>${cards}
    <div class="mm-style">
      <label for="mmStyleSel">${esc(t("ms_title"))}</label>
      <select id="mmStyleSel" class="keep-w"><option value="hub"${MENU_STYLE === "hub" ? " selected" : ""}>${esc(t("ms_hub"))}</option><option value="bar"${MENU_STYLE === "bar" ? " selected" : ""}>${esc(t("ms_bar"))}</option></select>
      <button type="button" class="btn small" data-mstyle="${MENU_STYLE === "bar" ? "hub" : "bar"}">${esc(t(MENU_STYLE === "bar" ? "ms_to_hub" : "ms_to_bar"))}</button>
    </div>`;
  overlay.querySelector("#mmCloseBtn").addEventListener("click", closeMobileMenu);
  const admEl = overlay.querySelector("[data-mmadmin]");
  if (admEl) admEl.addEventListener("click", () => { closeMobileMenu(); goToTab("adminpage"); });
  overlay.querySelector("#mmStyleSel").addEventListener("change", (e) => setMenuStyle(e.target.value));
}

// ---- Menu style: Hub (default) or Bottom bar ----
// Saved per account in calc_state `menu_style` = { style: "hub" | "bar" } and
// in localStorage `menu_style` (read by the head script for the first paint).
let MENU_STYLE = (() => { try { return localStorage.getItem("menu_style") === "bar" ? "bar" : "hub"; } catch (e) { return "hub"; } })();
let MENU_STYLE_USER = null; // the account whose saved choice was read
function menuStyleApply() {
  const bar = MENU_STYLE === "bar";
  document.documentElement.classList.toggle("mstyle-bar", bar);
  const vp = document.querySelector('meta[name="viewport"]');
  if (vp && window.VIEWPORT_BASE) vp.setAttribute("content", window.VIEWPORT_BASE + (bar ? ", viewport-fit=cover" : ""));
  try { localStorage.setItem("menu_style", MENU_STYLE); } catch (e) { /* storage blocked */ }
  if (!bar) mBarClose();
  mBarDraw();
  fillMenuStyleRow();
}
// The account's saved choice wins once its saved states are loaded (another
// phone / PC may have changed it); called after each calc_state preload.
function menuStyleFromSaved() {
  if (!CALC_STATE_CACHE || CALC_STATE_CACHE_USER !== USER_ID || MENU_STYLE_USER === USER_ID) return;
  MENU_STYLE_USER = USER_ID;
  const v = CALC_STATE_CACHE.menu_style;
  const s = v && (v.style === "bar" || v.style === "hub") ? v.style : null;
  if (s && s !== MENU_STYLE) { MENU_STYLE = s; menuStyleApply(); }
}
function setMenuStyle(style) {
  style = style === "bar" ? "bar" : "hub";
  const changed = style !== MENU_STYLE;
  MENU_STYLE = style;
  MENU_STYLE_USER = USER_ID;
  if (USER_ID) saveCalcState("menu_style", { style });
  menuStyleApply();
  const hub = document.getElementById("mobileMenuOverlay");
  // From the Hub: close it so the new style shows at once.
  if (changed && hub.classList.contains("open")) closeMobileMenu();
  if (MB_OPEN) mBarOpen(MB_OPEN);
}
function fillMenuStyleRow() {
  const el = document.getElementById("accMenuStyle");
  // Owner: the menu style is chosen only at the bottom of the Menu, not in the profile.
  if (el) { el.innerHTML = ""; el.hidden = true; }
}
document.addEventListener("click", (e) => {
  const b = e.target.closest("[data-mstyle]");
  if (!b) return;
  e.preventDefault();
  setMenuStyle(b.dataset.mstyle);
});

// ---- Bottom bar (phones <= 900 px with html.mstyle-bar) ----
// Home · Upgrade (Gears with Experts / Pets, Research) · Plan (Overview without the
// Dashboard: Backpack, State Timeline, Planning) · Bonus (every other card) · Me
// (account, language, menu style, Admin, About / Contact / Privacy, Log out).
const MB_SECS = [
  { key: "home", label: "mb_home", icon: "icons/logo-64.webp" },
  { key: "upgrade", label: "mb_upgrade", icon: "icons/quick/chief-gear.png" },
  { key: "plan", label: "mb_plan", icon: "icons/quick/calculator.png" },
  { key: "bonus", label: "mb_bonus", icon: "icons/quick/vip.png" },
  { key: "me", label: "mb_me" },
];
let MB_OPEN = null; // section whose sheet is open
let MB_LANG_OPEN = false; // Me: the language list unfolded
function mbCards(sec) {
  const cards = mmModel();
  if (sec === "upgrade") return cards.filter((c) => c.key === "Gears" || c.key === "Research");
  if (sec === "plan") {
    return cards.filter((c) => c.key === "Overview").map((c) => ({ ...c, blocks: c.blocks.map((b) => ({ ...b, items: b.items.filter((x) => !(x.btn && x.btn.dataset.tab === "overview")) })) }));
  }
  if (sec === "bonus") return cards.filter((c) => !["Overview", "Gears", "Research"].includes(c.key));
  return [];
}
function mbSecOfTab(tab) {
  if (tab === "overview") return "home";
  if (tab === "packcalendar") return "plan";
  if (tab === "aboutpage" || tab === "contactpage" || tab === "adminpage") return "me";
  for (const sec of ["upgrade", "plan", "bonus"]) if (mbCards(sec).some((c) => mmCardTabs(c).includes(tab))) return sec;
  return null;
}
function mbSignedIn() {
  const user = CURRENT_SESSION && CURRENT_SESSION.user;
  return user && user.email && !user.is_anonymous ? user : null;
}
function mbMeName() {
  const user = mbSignedIn();
  const nameEl = document.getElementById("commanderName");
  return (nameEl && nameEl.value.trim()) || (user ? user.email.split("@")[0] : "");
}
function mBarDraw() {
  const bar = document.getElementById("mBar");
  if (!bar) return;
  if (MENU_STYLE !== "bar") { if (bar.innerHTML) bar.innerHTML = ""; return; }
  const lit = MB_OPEN || mbSecOfTab(TAB);
  const user = mbSignedIn();
  const meIc = `<span class="mb-av${user ? " in" : ""}">${esc(user ? (mbMeName().charAt(0) || "?").toUpperCase() : "?")}</span>`;
  bar.innerHTML = MB_SECS.map((s) => `<button type="button" data-mbsec="${s.key}" class="${s.key === lit ? "on" : ""}"${s.key === "home" ? "" : ` aria-expanded="${MB_OPEN === s.key}"`}><span class="mb-ic">${s.icon ? `<img src="${esc(s.icon)}" alt="" />` : meIc}</span><span>${esc(t(s.label))}</span></button>`).join("");
}
// Me: the account card, then rows like a phone's settings list.
function mbMeHtml() {
  const user = mbSignedIn(), name = mbMeName();
  const li = (ic, label, right, attrs, cls) => `<button type="button" class="me-li${cls ? " " + cls : ""}" ${attrs}><span class="me-ic">${ic}</span><span class="me-l">${esc(label)}</span>${right || ""}</button>`;
  const chev = `<span class="me-ch" aria-hidden="true">&#8250;</span>`;
  // ✎ = the Commander name (same save as the top bar's account panel), for guests too.
  const edBtn = `<button type="button" class="me-ed" data-meedit aria-label="${esc(t("commander"))}" title="${esc(t("commander"))}">&#9998;</button>`;
  const nameBox = `<div class="me-name" data-mename hidden><input type="text" data-mename-in value="${esc((document.getElementById("commanderName") || {}).value || "")}" placeholder="${esc(t("commander"))}" aria-label="${esc(t("commander"))}" /><button type="button" class="btn small" data-mesave>${esc(t("save"))}</button></div>`;
  const acc = user
    ? `<div class="me-acc"><div class="me-top"><span class="me-av in">${esc((name.charAt(0) || "?").toUpperCase())}</span><span class="me-t"><b>${esc(name)}</b><small>${esc(t("me_cmd_change"))}</small><small class="ok">&#10003; ${esc(t(IS_OWNER ? "logged_in_owner" : "acc_signed_in"))}</small></span>${edBtn}</div>
        ${nameBox}</div>`
    : `<div class="me-acc"><div class="me-top"><span class="me-av g">${esc(name ? name.charAt(0).toUpperCase() : "?")}</span><span class="me-t"><b>${esc(name || t("me_guest"))}</b><small>${esc(t("me_guest_pitch"))}</small></span>${edBtn}</div>
        ${nameBox}
        <div class="me-gb"><button type="button" class="btn" data-meacc="signin">${esc(t("acc_sign_in"))}</button><button type="button" class="btn ghost" data-meacc="create">${esc(t("create_account"))}</button></div></div>`;
  const lang = languageList().find((l) => l.code === LANG);
  const langs = MB_LANG_OPEN ? `<div class="me-langs tn-lang-list">${languageList().map((l) => `<button type="button" data-melang="${esc(l.code)}" class="${l.code === LANG ? "on" : ""}"><span>${esc(l.name + (l.hidden ? " (hidden)" : ""))}</span>${l.code === LANG ? "&#10003;" : ""}</button>`).join("")}</div>` : "";
  const seg = `<span class="me-sg">${["hub", "bar"].map((s) => `<button type="button" data-mstyle="${s}" class="${MENU_STYLE === s ? "on" : ""}" aria-pressed="${MENU_STYLE === s}">${esc(t(s === "bar" ? "ms_bar" : "ms_hub"))}</button>`).join("")}</span>`;
  const admin = IS_OWNER && !isHiddenAdminBtn() ? `<div class="me-lst">${li("&#9881;", navLabel("adminpage"), chev, `data-tab="adminpage"`, "adm")}</div>` : "";
  return `${acc}
    <div class="me-lst">${li("&#127760;", t("language"), `<span class="me-v">${esc(lang ? lang.name : LANG)}</span>${chev}`, `data-melangopen aria-expanded="${MB_LANG_OPEN}"`)}${langs}
      <div class="me-li me-row"><span class="me-ic">&#9776;</span><span class="me-l">${esc(t("ms_title"))}</span>${seg}</div></div>
    ${admin}
    <div class="me-lst">${li(`<img src="icons/logo-64.webp" alt="" />`, t("about_title"), chev, `data-tab="aboutpage"`)}${li("&#9993;", t("contact_link"), chev, `data-tab="contactpage"`)}<a class="me-li" href="privacy.html"><span class="me-ic">&#128274;</span><span class="me-l">${esc(t("privacy_link"))}</span>${chev}</a></div>
    ${user ? `<div class="me-lst">${li("&#8617;", t("log_out"), "", "data-melogout", "out")}</div>` : ""}`;
}
function isHiddenAdminBtn() {
  const g = document.getElementById("adminNavGroup");
  return !g || g.style.display === "none";
}
function mBarSheetHtml(sec) {
  const title = t((MB_SECS.find((s) => s.key === sec) || {}).label || "mb_home");
  if (sec === "me") {
    const user = mbSignedIn();
    return `<div class="mb-sheet" role="dialog" aria-label="${esc(title)}"><div class="mb-grab"></div><div class="mb-shh"><b>${esc(title)}</b><span>${esc(user ? mbMeName() : t("me_guest"))}</span></div>${mbMeHtml()}</div>`;
  }
  const cards = mbCards(sec);
  const html = cards.map(mmCardHtml).join("");
  const n = cards.reduce((a, c) => a + c.blocks.reduce((k, b) => k + b.items.length, 0), 0);
  return `<div class="mb-sheet" role="dialog" aria-label="${esc(title)}"><div class="mb-grab"></div><div class="mb-shh"><b>${esc(title)}</b><span>${esc(n === 1 ? t("mb_page1") : t("mb_pages").replace("{n}", n))}</span></div>${html}</div>`;
}
function mBarOpen(sec) {
  const ov = document.getElementById("mBarOv");
  MB_OPEN = sec;
  ov.innerHTML = mBarSheetHtml(sec);
  ov.classList.add("open");
  mBarDraw();
}
function mBarClose() {
  const ov = document.getElementById("mBarOv");
  if (!ov) return;
  MB_OPEN = null;
  ov.classList.remove("open");
  ov.innerHTML = "";
}
document.getElementById("mBar").addEventListener("click", (e) => {
  const b = e.target.closest("[data-mbsec]");
  if (!b) return;
  const sec = b.dataset.mbsec;
  if (sec === "home") { mBarClose(); if (TAB !== "overview") goToTab("overview"); else mBarDraw(); window.scrollTo(0, 0); return; }
  // The open section's button again closes its sheet.
  if (MB_OPEN === sec) { mBarClose(); mBarDraw(); return; }
  mBarOpen(sec);
});
document.getElementById("mBarOv").addEventListener("click", (e) => {
  const pageBtn = e.target.closest("button[data-tab]");
  if (pageBtn) { mBarClose(); goToTab(pageBtn.dataset.tab); window.scrollTo(0, 0); return; }
  if (e.target.closest("[data-mstyle]")) return; // handled by the document listener
  // Me: language list, commander name, sign in / create account, log out.
  if (e.target.closest("[data-melangopen]")) { MB_LANG_OPEN = !MB_LANG_OPEN; mBarOpen("me"); return; }
  const lg = e.target.closest("[data-melang]");
  if (lg) { MB_LANG_OPEN = false; mBarClose(); mBarDraw(); if (lg.dataset.melang !== LANG) setLanguage(lg.dataset.melang); return; }
  if (e.target.closest("[data-meedit]")) {
    const box = e.currentTarget.querySelector("[data-mename]");
    if (box) { box.hidden = !box.hidden; if (!box.hidden) { const inp = box.querySelector("input"); if (inp) inp.focus(); } }
    return;
  }
  if (e.target.closest("[data-mesave]")) {
    const inp = e.currentTarget.querySelector("[data-mename-in]"), cn = document.getElementById("commanderName"), sv = document.getElementById("saveCommander");
    if (inp && cn && sv) { cn.value = inp.value; sv.click(); }
    mBarOpen("me");
    return;
  }
  const acc = e.target.closest("[data-meacc]");
  if (acc) { mBarClose(); mBarDraw(); openAccountModal(acc.dataset.meacc); return; }
  if (e.target.closest("[data-melogout]")) { const lo = document.getElementById("ownerLogoutBtn"); if (lo) lo.click(); return; }
  if (!e.target.closest(".mb-sheet")) { mBarClose(); mBarDraw(); }
});
document.addEventListener("keydown", (e) => { if (e.key === "Escape" && MB_OPEN) { mBarClose(); mBarDraw(); } });
// A wider screen (Fold opened, PC mode): the top menu is back, so drop the sheet.
try {
  const mq = window.matchMedia("(max-width: 900px)");
  mq.onchange = () => { if (!mq.matches && MB_OPEN) { mBarClose(); mBarDraw(); } };
} catch (e) { /* old browser */ }

function openMobileMenu() {
  renderMobileMenu();
  document.getElementById("mobileMenuOverlay").classList.add("open");
}
function closeMobileMenu() {
  document.getElementById("mobileMenuOverlay").classList.remove("open");
}

document.getElementById("mobileMenuBtn").addEventListener("click", openMobileMenu);

document.getElementById("mobileMenuOverlay").addEventListener("click", (e) => {
  const pageBtn = e.target.closest("button[data-tab]");
  if (pageBtn) {
    closeMobileMenu();
    goToTab(pageBtn.dataset.tab);
    return;
  }
  const catBtn = e.target.closest(".mm-category-btn");
  if (catBtn) {
    const cat = catBtn.closest(".mm-category");
    const wasOpen = cat.classList.contains("open");
    document.querySelectorAll(".mm-category.open").forEach((c) => c.classList.remove("open"));
    if (!wasOpen) cat.classList.add("open");
  }
});

// Loads/saves the player's display name shown in the sidebar.
async function loadCommander() {
  try {
    const rows = await sb(`profiles?id=eq.${USER_ID}&select=username`);
    if (rows && rows[0]) document.getElementById("commanderName").value = rows[0].username || "";
  } catch (e) {}
  renderAccountButton();
}
document.getElementById("saveCommander").addEventListener("click", async () => {
  const username = document.getElementById("commanderName").value.trim();
  try {
    await sb(`profiles?id=eq.${USER_ID}`, {
      method: "PATCH",
      body: JSON.stringify({ username, updated_at: new Date().toISOString() }),
    });
    toast("Saved");
    renderAccountButton();
  } catch (e) {
    toast("Couldn't save commander name", true);
  }
});

// Bumped on every page render. Pages wait for data before drawing, so each
// one checks this after loading: if a newer render started meanwhile (the
// user switched page), the older one stops instead of drawing over it.
let RENDER_SEQ = 0;
let RENDER_Y0 = 0;
// Central router: dispatches TAB to the right page renderer.
// The footer stays invisible until the first page is drawn (app.css
// html:not(.page-drawn) .site-footer), so it isn't shown at the top and then
// pushed down when the page arrives (layout shift).
// The loading layout from index.html (.boot-ld) stays until then; anything
// left of it goes here.
function pageDrawn() {
  document.documentElement.classList.add("page-drawn");
  document.querySelectorAll("#content > .boot-ld").forEach((x) => x.remove());
}
async function render() {
  const seq = ++RENDER_SEQ;
  mmPairNote(TAB); // Experts / Pets / Marketplace tiles open the page used last
  // PC text is 2 px bigger on every page but the Dashboard (pcBigger in the head)
  document.documentElement.classList.toggle("on-dash", TAB === "overview");
  // Bottom bar menu style: light the page's section; a page change closes its sheet.
  if (MB_OPEN) mBarClose();
  mBarDraw();
  // Page pop-ups: close them when the page changes.
  ["refineAdvModal", "drilldownModal", "gearSheet", "xsSheet"].forEach((id) => { const m = document.getElementById(id); if (m) m.style.display = "none"; });
  // The same page drawn again after a tap: keep its height and scroll place.
  const same = LAST_RENDER_TAB === TAB && !!content.firstElementChild, y0 = window.scrollY;
  RENDER_Y0 = y0; // the place before "Loading…" (Admin keeps it while admin.js loads)
  const putBoxes = same ? saveBoxScroll(content) : null;
  PAGE_ENTRY_SEQ = same ? -1 : seq;
  if (same) content.style.minHeight = content.offsetHeight + "px";
  // The first draw keeps the loading layout instead of "Loading…".
  if (!content.querySelector(":scope > .boot-ld")) content.innerHTML = `<div class="empty">Loading&hellip;</div>`;
  try {
    // Experts / Pets: entering the page picks its side (sideEntryTab).
    if (!same && sidePairOf(TAB)) {
      const tb = await sideEntryTab(TAB);
      if (seq !== RENDER_SEQ) return;
      if (tb !== TAB) {
        TAB = tb;
        try { localStorage.setItem("last_tab", TAB); } catch (e) { /* storage blocked */ }
        document.querySelectorAll("button[data-tab]").forEach((x) => x.classList.toggle("active", x.dataset.tab === TAB));
        history.replaceState({ tab: TAB }, "", location.pathname + location.search);
      }
    }
    // Visitor pages that follow Admin's visitor access: when the settings
    // didn't load (weak connection), stay on the page and try again instead of
    // sending the person to the Dashboard.
    if (!IS_OWNER && SITE_CONFIG_FAILED && ["budgets", "backpack", "packs", "mypacks", "purchases", "packcalendar"].includes(TAB)) {
      content.innerHTML = `<div class="empty">${esc(t("no_connection_retry"))}</div>`;
      await ensureSiteConfig();
      if (seq !== RENDER_SEQ) return;
      if (SITE_CONFIG_FAILED) { content.style.minHeight = ""; pageDrawn(); setTimeout(() => { if (seq === RENDER_SEQ) render(); }, 5000); return; }
    }
    // (Admin is for the owner only.) Sent to the Dashboard: the saved last page
    // stays, so a page the person can't open now isn't forgotten.
    if (!IS_OWNER && (TAB === "adminpage" || (TAB === "bestupgrades" && !visitorCan("bestupgrades")) || (TAB === "packcalendar" ? (!visitorCan("packs") || isHiddenFromVisitors("page", "packcalendar")) : (TAB === "budgets" || TAB === "backpack" || TAB === "packs" || TAB === "mypacks" || TAB === "purchases") ? !visitorCan(TAB === "mypacks" ? "packs" : TAB === "purchases" ? "budgets" : TAB) : isHiddenFromVisitors("page", TAB)))) { TAB = "overview"; history.replaceState({ tab: TAB }, "", location.pathname + location.search); }
    if (TAB === "overview") await renderOverview();
    else if (TAB === "budgets") await renderBudgetsPage();
    else if (TAB === "backpack") await renderInventory();
    else if (TAB === "statetimeline") await renderStateTimelinePage();
    else if (TAB === "packs") await renderPacksPage();
    else if (TAB === "mypacks") await renderMyPacksPage();
    else if (TAB === "purchases") await renderPurchasesPage();
    else if (TAB === "bestupgrades") await renderBestUpgradesPage();
    else if (TAB === "packcalendar") await renderPackCalendarPage();
    else if (TAB === "charmscalc") await renderCharmsCalc();
    else if (TAB === "chiefgear") await renderChiefGearCalc();
    else if (TAB === "herogearcalc") await renderGearLevelingGroup(content);
    else if (TAB === "skingallery") await renderSkinGallery();
    else if (TAB === "islandgallery") await renderIslandGallery();
    else if (TAB === "facilitypage") await renderFacilityPage();
    else if (TAB === "t12research") await renderT12ResearchPage();
    else if (TAB === "rfclab") await renderRfcLabPage();
    else if (TAB === "t11helios") await renderT11HeliosPage();
    else if (TAB === "researchcenter") await renderResearchCenterPage();
    else if (TAB === "petsdata") await renderPetsDataPage();
    else if (TAB === "refinepage") await renderRefinePage();
    else if (TAB === "expertspage") await renderExpertsPage();
    else if (TAB === "expertsresearchpage") await renderExpertsResearchPage();
    else if (TAB === "adminpage") await renderAdminPage();
    else if (TAB === "contactpage") await renderContactPage();
    else if (TAB === "aboutpage") await renderAboutPage();
    else if (TAB === "alliancetechpage") await renderAllianceTechPage();
    else if (TAB === "albumtundrapage") await renderAlbumTundraPage();
    else if (TAB === "collectiongallerypage") await renderCollectionGalleryPage();
    else if (TAB === "extrabonusheroes") await renderExtraBonusHeroes();
    else if (TAB.startsWith("extrabonus:")) {
      const catName = TAB.slice(11);
      if (catName === "Vip Tier") await renderVipTierTable(content);
      else await renderCategoryPage(catName);
    }
    else if (TAB.startsWith("buffcat:")) {
      const catName = TAB.slice(8);
      if (catName === "Vip Tier") await renderVipTierTable(content);
      else if (CATEGORY_GROUPS[catName]) await renderGroupPage(catName);
      else await renderCategoryPage(catName);
    }
    // Owner: the "Best next here" card on the planner pages (Best upgrades).
    if (seq === RENDER_SEQ && visitorCan("bestupgrades") && ADV_CARD_TABS[TAB]) advCardInject(seq).catch((e) => console.warn("best upgrades", e));
    // "Opens around day N" notes from the state age, under the page title.
    if (seq === RENDER_SEQ && STATE_UNLOCKS.some((u) => u.tabs.includes(TAB))) {
      await ensureStateAge();
      const html = seq === RENDER_SEQ ? stateLockNotesHtml(TAB) : "";
      const head = html && !content.querySelector("[data-salock]") ? content.querySelector(".plx-head, .page-head") : null;
      if (head) head.insertAdjacentHTML("afterend", html);
    }
    // The admin's page note (Admin → Menu & pages), under the page title.
    const note = seq === RENDER_SEQ ? pageNoteFor(TAB) : "";
    if (note && !content.querySelector("[data-pagenote]")) {
      const nh = `<div class="page-note" data-pagenote>${esc(note).replace(/\n/g, "<br>")}</div>`;
      const head = content.querySelector(".plx-head, .page-head");
      if (head) head.insertAdjacentHTML("afterend", nh); else content.insertAdjacentHTML("afterbegin", nh);
    }
    if (seq === RENDER_SEQ) {
      // (an Experts / Pets side flip keeps the switch in place itself: sideHold)
      if (same) { putBoxes(); if (!SIDE_HOLD) window.scrollTo(0, y0); }
      if (!content.dataset.holdUntilReady) content.style.minHeight = "";
      LAST_RENDER_TAB = TAB;
      pageDrawn();
      // Experts / Pets: the side not shown saves its Budgets needs too (quietly).
      if (!same && sidePairOf(TAB) && sidePairOpen(sidePairOf(TAB))) sideBgNeeds(TAB);
    }
  } catch (e) {
    if (seq !== RENDER_SEQ) return; // a newer page is showing; don't cover it
    LAST_RENDER_TAB = TAB;
    pageErrorPanel(e);
  }
}
function pageErrorPanel(e) {
  pageDrawn();
  content.style.minHeight = "";
  content.innerHTML = `<div class="panel"><div class="empty"><div class="big">Something went wrong loading this tab.</div>${esc((e && e.message) || String(e))}</div></div>`;
}
// A page redrawn outside render() (after a tap, a finished plan …) that
// fails shows the same panel as render(), only while that page is still the
// one on screen (SEQ = RENDER_SEQ when the redraw started).
function pageRedrawFailed(e, seq) {
  if (seq !== RENDER_SEQ || (e && e.superseded)) return;
  console.error(e);
  pageErrorPanel(e);
}

// ============================================================
// OVERVIEW / STATS DASHBOARD
// Aggregates buff data across all categories into per-troop-type
// (Infantry/Lancer/Marksman) stat cards with top-source breakdowns.
// ============================================================
// Prettifies internal source keys for display only; sorting/whitelisting
// still uses the raw key so live-calc values correctly overwrite their
// static counterparts under the same key. Global scope so both the
// dashboard cards and the standalone drilldown modal can use it.
const SOURCE_DISPLAY_NAME = {
  Chief: "Chief Gears",
  "Chief Bonus": "Chief Gears Bonus",
  Charm: "Chief Charm",
  "Hero Gears": "Heroes Gears",
  Skins: "Skin Gallery",
  "Alliance Buff": "Alliance Tech",
  "Album Buff": "Tundra Album",
  Gallery: "Collection Gallery",
  "T11 Helios Research": "T11 Research",
  "T12 Research": "T12 Research",
  "Vip Tier": "VIP",
  Jero: "Jeronimo",
};
function displaySourceName(key) {
  return dataName(SOURCE_DISPLAY_NAME[key] || key);
}
// Dashboard sources (Admin → Dashboard sources): site_config
// "dashboard_sources" = { extra: [buff categories counted as flat bonuses],
// order: [source keys, breakdown order] }. Nothing saved = the built-in lists.
// The breakdown order of the built-in sources (matches the menu).
const DASH_SOURCE_ORDER_DEFAULT = [
  "VIP", "Jero", "Natalia", "Skins", "Islands", "Roster Heroes",
  "Chief", "Chief Bonus", "Charm", "Hero Gears",
  "Pets Level", "Pets Refine",
  "Facility", "Alliance Buff", "Album Buff", "Gallery",
  "Research Center", "T11 Helios Research", "T12 Research", "Experts", "Experts Research",
];
function dashSourcesConfig() {
  const v = typeof siteConfig === "function" ? siteConfig("dashboard_sources", null) : null;
  return { extra: v && Array.isArray(v.extra) ? v.extra.filter((x) => typeof x === "string" && x) : [], order: v && Array.isArray(v.order) ? v.order.filter((x) => typeof x === "string" && x) : [] };
}
// The breakdown order: built-in order with the special-skill heroes after
// Natalia and the extra sources last, then the admin's order on top.
function dashSourceOrderBase(heroes, extra) {
  const list = DASH_SOURCE_ORDER_DEFAULT.slice();
  (heroes || []).filter((h) => !list.includes(h)).forEach((h, i) => list.splice(list.indexOf("Natalia") + 1 + i, 0, h));
  (extra || []).filter((x) => !list.includes(x)).forEach((x) => list.push(x));
  return list;
}
function dashSourceOrder(heroes, extra) {
  const list = dashSourceOrderBase(heroes, extra);
  const saved = dashSourcesConfig().order.filter((k) => list.includes(k));
  return saved.length ? [...saved, ...list.filter((k) => !saved.includes(k))] : list;
}

