  preloadCalcStates();
  const fixed = dashFixedReads();
  const skinsPromise = Promise.all([ensureGalleryUncounted(), fixed.skins]).then(([, rows]) => rows);
  const [[columns, rows], allSkins, ISLAND_CATEGORIES, ROSTER_HERO_CATALOG, ROSTER_SAVED, ROSTER_PLAYER_HEROES, ROSTER_STAR_ROWS, ROSTER_WIDGET_ROWS,
    , GALLERY_SAVED, JERO_SAVED, NATALIA_SAVED, ALBUM_SAVED, ROSTER_BACKPACK, GALLERY_LEVEL_ROWS, ALBUM_LEVEL_ROWS] = await Promise.all([
    fixed.buff,
    skinsPromise,
    // Which skins.category values actually represent an Island sub-category
    // (Attack/Defense/Lighthouse/MVP/Islands Guide, etc) - driven by the same
    // table the Islands page itself uses, cached across the session so this
    // small, rarely-changing table isn't re-fetched on every page visit.
    ensureIslandCategories(),
    // Roster heroes (Infantry/Lancers/Marksman) - fetched here, early, so
    // the stat totals below can include them when a troop's "used" flag is on.
    fixed.heroes,
    loadCalcState("dashboard_roster"),
    fixed.player_heroes,
    fixed.star_stats,
    fixed.widget_stats,
    // live data from the calculators, for the Charm/Chief/Hero Gears/etc. sources below
    Promise.all([ensureCharmData(), loadChiefGearRows(), ensureHeroGearData(), ensureT12StateData(), ensureRCData(), ensureT11StateData(), ensurePetsData(), ensureVipData(), ensureExpertsTroopStatsData(), ensureExpertsResearchDataGlobal(), skinsPromise.then(ensureGlobeLevelData), ensureResearchPageCountedData(), ensureStateAge(), ensurePackLinks().catch(() => null)]),
    loadCalcState("collection_gallery"),
    loadCalcState("hero_stars_jero"),
    loadCalcState("hero_stars_natalia"),
    loadCalcState("album_tundra"),
    loadCalcState("backpack").catch(() => null), // roster cards: shards still short
    // Collection Gallery / Tundra Album levels for their "of max" (null = the built-in numbers).
    // (same request and kept copy as their own pages)
    keptRows("collection_gallery_levels", `collection_gallery_levels?select=${upId("collection_gallery_levels")}stat_type,value_pct&order=sort_order.asc`).catch(() => null),
    keptRows("tundra_album_levels", `tundra_album_levels?select=${upId("tundra_album_levels")}stat_type,value_pct&order=sort_order.asc`).catch(() => null),
  ]);
  // Heroes Special Skills: every hero column in the buff table (Jero, Natalia
