function itemReg(name) { const reg = itemRegistry(); let r = reg[name]; if (!r && reg !== ITEM_REG_EMPTY) { const a = itemPageMaps().alias[name]; if (a) r = reg[a]; } return r && typeof r === "object" ? r : null; }
