    out[pg] = (Array.isArray(v && v[pg]) ? v[pg] : []).filter((r) => r && r.node && Number(r.from) >= 1 && Array.isArray(r.needs)).map((r) => ({
      node: String(r.node), from: Math.round(Number(r.from)), ...(r.any ? { any: true } : {}),
      needs: r.needs.filter((n) => n && n.node && Number(n.lv) >= 1).map((n) => ({ node: String(n.node), lv: Math.round(Number(n.lv)) })),
    })).filter((r) => r.needs.length);
