// person's targets. Steps that raise no stat are filled last.
const UPGRADE_ORDER_DEFAULT = [["Infantry", "Health"], ["Infantry", "Defense"], ["Marksman", "Lethality"], ["Marksman", "Attack"], ["Lancer", "Lethality"], ["Lancer", "Attack"], ["Marksman", "Health"], ["Marksman", "Defense"], ["Infantry", "Lethality"], ["Infantry", "Attack"], ["Lancer", "Health"], ["Lancer", "Defense"]];
