function cdaItemIcon(n, tr) { const k = /^isl:/.test(n) ? (tr && tr.alias) || "Mythic Island Shards" : n; try { return materialIconSrc(k) || bpIcon({ name: k }) || BP_EXTRA_ICONS[k] || ""; } catch (e) { return ""; } }
