// What a plan adds to the stats of some tracks ("+6% LETH · HP"); tracks of one piece (grp)
// share their stats and count once.
const REACH_STAT_ABBR = { Attack: "ATK", Defense: "DEF", Lethality: "LETH", Health: "HP" };
function reachTroopGain(tracks, plan) {
  const before = {}, out = {}, seen = new Set();
  tracks.forEach((tr) => { before[tr.id] = tr.from; });
  tracks.forEach((tr) => {
    if (tr.grp) { if (seen.has(tr.grp)) return; seen.add(tr.grp); }
    const a = tr.gain(plan.lv[tr.id], plan.lv) || {}, b = tr.gain(tr.from, before) || {};
    Object.keys(a).forEach((k) => { const d = (a[k] || 0) - (b[k] || 0); if (d > 1e-9) out[k] = (out[k] || 0) + d; });
  });
  return out;
}
function reachGainText(g) {
  const ks = ["Attack", "Defense", "Lethality", "Health"].filter((k) => g[k] > 0.005);
  if (!ks.length) return "";
  const r = (v) => bidiNum(`+${Math.round(v * 10) / 10}%`);
  if (ks.length > 1 && ks.every((k) => Math.abs(g[k] - g[ks[0]]) < 0.05)) return `${r(g[ks[0]])} ${ks.map((k) => REACH_STAT_ABBR[k]).join(" · ")}`;
  return ks.map((k) => `${r(g[k])} ${REACH_STAT_ABBR[k]}`).join(" ");
}

async function updateHeroGearTotals() {
  if (!HERO_GEAR_TABLES_CACHE) return;
  const HERO_GEAR_MATERIAL_COLS = [
    ["mithril", "Mithril"],
    ["mythic_gear", "Mythic Gear"],
    ["xp_component", "XP Component"],
    ["essence_stones", "Essence Stones"],
  ];

  // One real inventory covers all 3 loadouts (owned amounts are shared
  // under a single key), while needed / still-needed reflects only the
  // set currently selected on the page.
  const matTotals = {};
  const setState = HERO_GEAR_SETS[heroGearActiveSet];
  HERO_GEAR_TROOPS.forEach((troop) => {
    HERO_GEAR_PIECE_NAMES.forEach((piece) => {
      GEAR_LEVELING_TABLES.forEach((t) => {
        const rows = HERO_GEAR_TABLES_CACHE[t];
        if (!rows.length) return;
        const st = setState[troop][piece][t];
        const fromIdx = Math.min(st.from, st.to);
        const toIdx = Math.max(st.from, st.to);
        for (let i = fromIdx + 1; i <= toIdx; i++) {
          HERO_GEAR_MATERIAL_COLS.forEach(([col, label]) => {
            const v = Number(rows[i][col]) || 0;
            if (v) matTotals[label] = (matTotals[label] || 0) + v;
          });
        }
      });
    });
  });

  renderChiefGearResourcesBar("heroGearOwned", matTotals, ["XP Component", "Essence Stones", "Mithril", "Mythic Gear"], updateHeroGearTotals, "hero_gear");

  updateHeroGearCurrentStats();
}

// Computes current Attack/Defense/Lethality/Health bonus per troop
// type: Mastery Forging contributes Lethality+Health only; Mithril
// milestones crossed on the Enhance track contribute all 4 stats.
// Pure computation, reusable by both this page and the Stats dashboard.
// stateObj must have the same shape as HERO_GEAR_STATE.
function computeHeroGearStats(stateObj) {
  if (!HERO_GEAR_TABLES_CACHE) return {};
  const mfRows = HERO_GEAR_TABLES_CACHE["Hero Gear Mastery Forging"];
  const enhRows = HERO_GEAR_TABLES_CACHE["Enhance Combined"];
  if (!mfRows || !mfRows.length) return {};

  const out = {};
  HERO_GEAR_TROOPS.forEach((troop) => {
    const statTotals = { Attack: 0, Defense: 0, Health: 0, Lethality: 0 };
    const continuousMax = { Health: 0, Lethality: 0 };
    HERO_GEAR_PIECE_NAMES.forEach((piece) => {
      const mfIdx = Math.min(stateObj[troop][piece]["Hero Gear Mastery Forging"].from, heroTrackPickIdx("Hero Gear Mastery Forging"));
      const mfStat = parseStatPct(mfRows[mfIdx]?.stat) || 0;
      // Mastery Forging is a MULTIPLIER on the piece's Enhance stat, not a
      // stat of its own: piece stat = Enhance % x (1 + Mastery %).
      // e.g. Mastery 20 (+200%) x Enhance 100 (+50%) = +150% for that piece;
      //      with Enhance 200 (+100%) it's +300%.
      const mfMult = 1 + mfStat / 100;
      if (enhRows && enhRows.length) {
        const enhIdx = Math.min(stateObj[troop][piece]["Enhance Combined"].from, heroTrackPickIdx("Enhance Combined"));
        const continuousStat = (parseStatPct(enhRows[enhIdx]?.stat) || 0) * mfMult;
        HERO_GEAR_ENHANCE_CONTINUOUS_STATS[piece].forEach((stat) => {
          continuousMax[stat] += continuousStat;
        });
        const ms = heroGearMilestones(enhRows, enhIdx, piece);
        statTotals.Attack += ms.Attack;
        statTotals.Defense += ms.Defense;
      }
    });
    statTotals.Health += continuousMax.Health;
    statTotals.Lethality += continuousMax.Lethality;
    out[troop] = statTotals;
  });
  return out;
}

// Builds a synthetic "everything at max level" state, same shape as
// HERO_GEAR_STATE, for computing the Max Possible ceiling.
function maxedHeroGearState() {
  const out = {};
  HERO_GEAR_TROOPS.forEach((troop) => {
    out[troop] = {};
    HERO_GEAR_PIECE_NAMES.forEach((piece) => {
      out[troop][piece] = {};
      GEAR_LEVELING_TABLES.forEach((t) => {
        out[troop][piece][t] = { from: heroTrackCapIdx(t) };
      });
    });
  });
  return out;
}

// One hero gear piece's own stats at its current (role "from") or target ("to") levels.
function heroGearPieceStats(stateObj, troop, piece, role) {
  const out = { Attack: 0, Defense: 0, Health: 0, Lethality: 0 };
  const mfRows = HERO_GEAR_TABLES_CACHE && HERO_GEAR_TABLES_CACHE["Hero Gear Mastery Forging"];
  const enhRows = HERO_GEAR_TABLES_CACHE && HERO_GEAR_TABLES_CACHE["Enhance Combined"];
  if (!mfRows || !mfRows.length || !enhRows || !enhRows.length) return out;
  const st = stateObj[troop][piece];
  const mfIdx = Math.min(st["Hero Gear Mastery Forging"][role], heroTrackPickIdx("Hero Gear Mastery Forging"));
  const enhIdx = Math.min(st["Enhance Combined"][role], heroTrackPickIdx("Enhance Combined"));
  const cont = (parseStatPct(enhRows[enhIdx]?.stat) || 0) * (1 + (parseStatPct(mfRows[mfIdx]?.stat) || 0) / 100);
  const ms = heroGearMilestones(enhRows, enhIdx, piece);
  HERO_GEAR_ENHANCE_CONTINUOUS_STATS[piece].forEach((k) => { out[k] += cont; });
  out.Attack += ms.Attack;
  out.Defense += ms.Defense;
  return out;
}
function fillHeroGearPieceStats() {
  const state = HERO_GEAR_SETS[heroGearActiveSet];
  if (!state || !HERO_GEAR_TABLES_CACHE) return;
  const ABBR = { Attack: "ATK", Defense: "DEF", Lethality: "LETH", Health: "HP" };
  document.querySelectorAll("[data-hgstat]").forEach((box) => {
    const [troop, piece] = box.dataset.hgstat.split("|");
    if (!state[troop] || !state[troop][piece]) return;
    const now = heroGearPieceStats(state, troop, piece, "from"), tgt = heroGearPieceStats(state, troop, piece, "to");
    const keys = [...HERO_GEAR_ENHANCE_MILESTONE_STATS[piece], ...HERO_GEAR_ENHANCE_CONTINUOUS_STATS[piece]];
    box.innerHTML = plxPieceStatHtml(keys.map((k) => ({ label: ABBR[k], now: now[k], target: Math.max(now[k], tgt[k]) })));
  });
}
// Heroes Gears "can reach" marks: the set on screen,
