  const costs = {};
  GEAR_LEVELING_TABLES.forEach((tn) => { costs[tn] = (HERO_GEAR_TABLES_CACHE[tn] || []).map((r) => { const c = {}; cols.forEach(([col, lab]) => { const v = Number(r[col]) || 0; if (v) c[lab] = v; }); return c; }); });
