  el.addEventListener("click", (e) => { if (e.target.closest("[data-dashtoday]")) { PACK_CAL_WEEK = 0; PACK_CAL_DAY = null; PACK_CAL_DAY_MORE = false; goToTab("packcalendar"); } });
