  const rosterNames = ["Infantry", "Lancers", "Marksman"].map((k) => { const e = (rosterSaved || {})[k]; const id = !e ? "" : typeof e === "string" ? e : e.heroId || ""; const h = id && (heroes || []).find((x) => x.id === id); return h ? h.name : ""; }).filter(Boolean);
  // All mythic heroes' widgets sit in ONE "Widgets" box (tap it to edit each
