  const widgetGens = () => [...new Set(rosterGens.concat(wState.gens))].filter((g) => !wState.genHide.includes(g)).sort((a, b) => b - a);
  const widgetHeroes = () => mythics.filter((h) => (wState.add.includes(h.name) || Number(bp[`${h.name} Widgets`]) > 0) && !wState.hide.includes(h.name))
