// Which game Backpack tab each item Scan reads is in, and the items' order in
// that tab (order from the owner's screenshots and the
// order the items were learned in). Items without a known place (Marks of
// Valor, a Gen's widget box, heroes' own shards) aren't in the order, so a
// missing one is never offered for "set to 0".
const SCAN_RES_TAB = ["Fire Crystal", "Refined FC", "FC Shard", "FC Chest", "FC Crate",
  "Custom Resource Chest Lv.1", "Custom Resource Chest Lv.2", "Custom Resource Chest Lv.3",
  "Custom Resource Chest Lv.1 (protected)", "Custom Resource Chest Lv.2 (protected)", "Custom Resource Chest Lv.3 (protected)", "Resource Chest"];
const SCAN_TAB_ORDER = {
  res: SCAN_RES_TAB,
  // The Mythic Gear box sits right after Pet Chest, next to the Gen widget box (owner's screenshots).
  other: ["Lucky Gear Chest", "Random Chief Gear Chest", "Random Charm Chest", "Chief Gear Chest", "Pet Chest", "Mythic Gear", "Mystery Points",
    "Sail of Conquest", "Fiery Heart", "Compass", "Books of Knowledge", "General Sigils",
    "Cyrille Sigils", "Agnes Sigils", "Holger Sigils", "Romulus Sigils", "Fabian Sigils", "Baldur Sigils", "Valeria Sigils", "Ronne Sigils", "Kathy Sigils", "Gareth Sigils", "Justus Sigils",
    "Serum", "Potion", "Manual", "Advanced Marks", "Common Marks", "Jewel Secrets", "Charm Designs", "Charm Guides", "Amber",
    "Design Plan", "Polishing Solution", "Hardened Alloy", "Mithril", "Essence Stones", "XP 10", "XP 100",
    "Mythic General Hero Shard", "Epic General Hero Shard", "Rare General Hero Shard"],
};
// Game tab of a Backpack item: Admin → Backpack Items "Game tab" (site_config
// backpack_items item.tab) first, else what Scan knows.
// "" = not known; "none" = not in the game Backpack (Summary screen items).
function bpItemTabBuiltin(n) {
  if (/speedup/i.test(n)) return "speed";
  if (SCAN_RES_TAB.includes(n) || ["Gems", "Meat", "Wood", "Coal", "Iron"].includes(n)) return "res";
  if (SCAN_TAB_ORDER.other.includes(n) || / (Sigils|Shards|Widgets)$/.test(n) || n === "Marks of Valor" || SCAN_ITEM_NAMES.includes(n)) return "other";
  const l = SCAN_LEARNED.find((e) => e.n === n);
  return l && l.tab ? l.tab : "";
}
function bpItemTab(n) {
  const saved = typeof siteConfig === "function" ? siteConfig("backpack_items", null) : null;
  const it = saved && Array.isArray(saved.items) ? saved.items.find((x) => x && x.name === n) : null;
  return it && it.tab ? it.tab : bpItemTabBuiltin(n);
}
const scanItemTab = (n) => bpItemTab(n) || "other";
// Tiles taught on the site: site_config "scan_learned" =
// { items: [{ n: item name, f: picture grid (base64), tab, after: the known
// item just before it in the screenshot }] } — taught by the owner only, used
// by everyone's Scan.
let SCAN_LEARNED = [];
const SCAN_SKIP = "__skip__"; // a taught "never ask again" picture
const scanB64ToFeat = (v) => { try { return Uint8Array.from(atob(v), (c) => c.charCodeAt(0)); } catch (e) { return new Uint8Array(0); } };
async function scanLearnedLoad() {
  await ensureSiteConfigKey("scan_learned");
  const all = ((siteConfig("scan_learned", null) || {}).items || []).slice();
  // Items read from the Summary screen (Meat, Wood, Coal, Iron, Gems, Steel, Pet
  // Food, Chief Stamina, Hero XP) are never taught from tiles: a tile of them is
  // a bundle, and its count isn't the total.
  SCAN_LEARNED = all.filter((e) => e && e.n && e.f && !SCAN_SUMMARY_ROWS.some(([, n]) => n === e.n)).map((e) => ({ ...e, g: scanB64ToFeat(e.f) })).filter((e) => e.g.length === SCAN_FEAT_W * SCAN_FEAT_H * 3);
  return SCAN_LEARNED;
}
// "Resource & Speedup Summary", Resources tab: the last number on each row
// is Total Resources (city + backpack).
const SCAN_SUMMARY_ROWS = [[/\bgems?\b/i, "Gems"], [/\bmeat\b/i, "Meat"], [/\bwood\b/i, "Wood"], [/\bcoal\b/i, "Coal"], [/\biron\b/i, "Iron"], [/\bsteel\b/i, "Steel"], [/chief\s*stamina/i, "Chief Stamina"], [/hero\s*xp/i, "Hero XP"], [/pet\s*food/i, "Food"]];
// Code loaded on demand: each file is a plain script whose functions and variables
// join the page's own, loaded the first time it is needed, so visitors who never
// open those pages don't download it. What other pages use stays here in app.js.
//   admin.js   - the Admin page (owner only)
//   scan.js    - the Backpack's Scan
//   packs.js   - the Packs page, My packs and the Pack calendar
//   gallery.js - Skin Gallery, Islands and Facility
//   purchases.js - My Purchases
//   budgets.js - Budgets
// Each file carries its build id (window.<NAME>_BUILD = the "?v=" below, written by
// tools/stamp.js, which also makes the packed copies loaded here). The server ignores
// "?v=", so a tab left open since before an update gets the new file: then the page
// reloads once (sessionStorage "<name>_reload_for") to the new app.js instead of
// running mismatched code; if it still doesn't match, the promise fails with
// err.stale and the caller says so.
const CODE_FILES = {
  admin: "admin.min.js?v=afc8ef38aa",
  scan: "scan.min.js?v=64a7ef20ff",
  packs: "packs.min.js?v=f248b1fa8f",
  gallery: "gallery.min.js?v=28a7717641",
  purchases: "purchases.min.js?v=b3f8741082",
  budgets: "budgets.min.js?v=a42622de18",
};
const CODE_P = {}, CODE_OK = {};
function loadCode(name) {
  if (!CODE_P[name]) {
    CODE_P[name] = new Promise((resolve, reject) => {
      const s = document.createElement("script");
      s.src = CODE_FILES[name];
      const want = new URL(s.src, location.href).searchParams.get("v");
      s.onload = async () => {
        if (window[`${name.toUpperCase()}_BUILD`] === want) { CODE_OK[name] = true; resolve(); return; }
        let again = true;
        try { again = sessionStorage.getItem(`${name}_reload_for`) === want; if (!again) sessionStorage.setItem(`${name}_reload_for`, want); } catch (e) { again = true; }
        if (!again) {
          // let saves still on their way finish first
          for (let i = 0; i < 50; i++) { const busy = Object.values(CALC_SAVE_QUEUE).concat(Object.values(ROW_PATCH_QUEUE)).map((q) => q.running).filter(Boolean); if (!busy.length) break; await Promise.all(busy).catch(() => {}); }
          location.reload();
          return;
        }
        reject(Object.assign(new Error(`${name}.js is from another version`), { stale: true }));
      };
      s.onerror = () => { CODE_P[name] = null; s.remove(); reject(new Error(`${name}.js didn't load`)); };
      document.head.appendChild(s);
    });
  }
  return CODE_P[name];
}
// The tabs each page file draws (a stub below loads the file, then draws the page).
const CODE_TABS = { packs: ["packs", "mypacks", "packcalendar"], gallery: ["skingallery", "islandgallery", "facilitypage"], purchases: ["purchases"], budgets: ["budgets"] };
// A page stub's first step: true once the page's file is loaded and this draw is still
// the one wanted (RENDER_SEQ and TAB unchanged). "Loading…" (from render()) stays while
// it loads; a stale copy after the reload says so; no connection says so and tries
// again in 5 s while the person is still on those pages.
async function pageCodeReady(name) {
  if (CODE_OK[name]) return true;
  const seq = RENDER_SEQ, tabs = CODE_TABS[name];
  try { await loadCode(name); } catch (e) {
    if (seq !== RENDER_SEQ || !tabs.includes(TAB)) return false;
    content.innerHTML = `<div class="empty">${esc(t(e && e.stale ? "page_update_reload" : "no_connection_retry"))}</div>`;
    content.style.minHeight = "";
    if (!(e && e.stale)) setTimeout(() => { if (seq === RENDER_SEQ && tabs.includes(TAB)) render(); }, 5000);
    return false;
  }
  return seq === RENDER_SEQ && tabs.includes(TAB);
}
let SCAN_CODE_OK = false;
function loadScanCode() { return loadCode("scan").then(() => { SCAN_CODE_OK = true; }); }
// The Backpack's Scan button: loads scan.js (once), then opens Scan
// (openBackpackScanMain in scan.js).
async function openBackpackScan(groups, bp, done, more) {
  if (!SCAN_CODE_OK) {
    const btn = document.getElementById("bpScan");
    if (btn) btn.setAttribute("aria-busy", "true");
    try { await loadScanCode(); } catch (e) {
      if (btn) btn.removeAttribute("aria-busy");
      toast(t(e && e.stale ? "scan_update_reload" : "no_connection_retry"), true);
      return;
    }
    if (btn) btn.removeAttribute("aria-busy");
    // the Backpack was left while scan.js loaded
    if (btn && !btn.isConnected) return;
  }
  return openBackpackScanMain(groups, bp, done, more);
}

// ============================================================
// GENERIC BUFF CATEGORY SYSTEM
// A single shared "master" matrix table (buff_tables/columns/rows/
// cells) backs every dynamic nav category (Facility, Research,
// Chief, Charm, Pets, VIP Tier, War Acd., etc). Each category is a
// column; each row is a named stat line (e.g. "Infantry ATT").
// Categories can be grouped into sub-nav (see CATEGORY_GROUPS) or
// nested under Heroes/Extra Buff.
// ============================================================
// Fetches (or lazily creates) the one shared buff matrix table.
let BUFF_TABLE_PROMISE = null;
function ensureBuffTable() {
  if (BUFF_TABLE_ID) return Promise.resolve(BUFF_TABLE_ID);
  // Callers running at the same time share one lookup (and can never both
  // create a table).
  if (!BUFF_TABLE_PROMISE) {
    BUFF_TABLE_PROMISE = ensureBuffTableOnce().catch((e) => { BUFF_TABLE_PROMISE = null; throw e; });
  }
  return BUFF_TABLE_PROMISE;
}
async function ensureBuffTableOnce() {
  if (BUFF_TABLE_ID) return BUFF_TABLE_ID;
  // The buff matrix is site reference data: everyone (visitors included)
  // reads the owner's master table. Only the owner can ever create one.
  const existing = await sb(`buff_tables?select=id&user_id=eq.${PROGRESSION_OWNER_ID}&name=neq.VIP%20Tier&order=created_at.asc&limit=1`);
  if (existing && existing.length) {
    BUFF_TABLE_ID = existing[0].id;
  } else if (IS_OWNER) {
    const [created] = await sb(`buff_tables`, {
      method: "POST",
      body: JSON.stringify({ user_id: USER_ID, name: "Buffs", sort_order: 0 }),
    });
    BUFF_TABLE_ID = created.id;
  } else {
    BUFF_TABLE_ID = null;
  }
  return BUFF_TABLE_ID;
}

// Rebuilds the sidebar's dynamic category buttons from the buff
// matrix's columns, excluding any pulled into Heroes/Extra Buff/
// grouped sub-nav so they don't appear twice.
// At start (boot) the table and its columns come in one request; when the
// Dashboard's buff read already ran, its menu-ordered columns are used.
let BUFF_SORTED_COLS = null; // { id, cols } from dashFixedReads, taken once by boot
async function loadBuffColumnsAtStart() {
  if (DASH_DATA_CACHE.buff) await DASH_DATA_CACHE.buff.catch(() => {});
  const kept = BUFF_SORTED_COLS;
  BUFF_SORTED_COLS = null;
  if (kept && kept.id === BUFF_TABLE_ID) return kept.cols;
  if (BUFF_TABLE_ID || BUFF_TABLE_PROMISE) return null;
  const [tb] = (await sb(`buff_tables?select=id,cs:buff_columns(id,name,category)&cs.order=sort_order.asc&user_id=eq.${PROGRESSION_OWNER_ID}&name=neq.VIP%20Tier&order=created_at.asc&limit=1`)) || [];
  if (!tb) return null; // no table yet: the usual lookup (the owner's creates one)
  if (!BUFF_TABLE_ID) BUFF_TABLE_ID = tb.id;
  return tb.id === BUFF_TABLE_ID ? tb.cs || [] : null;
}
async function loadBuffCategories(atStart) {
  let columns = atStart ? await loadBuffColumnsAtStart() : null;
  if (!columns) {
    await ensureBuffTable();
    columns = !BUFF_TABLE_ID ? [] : await sb(`buff_columns?table_id=eq.${BUFF_TABLE_ID}&select=id,name,category&order=sort_order.asc`);
  }
  const grouped = [];
  const seen = new Map();
  for (const c of columns) {
    const key = c.category || c.name;
    if (!seen.has(key)) {
      seen.set(key, { name: key, columns: [] });
      grouped.push(seen.get(key));
    }
    seen.get(key).columns.push(c);
  }
  BUFF_CATEGORIES = grouped;

  const HERO_SUBCATS = new Set(["Jero", "Natalia", "Hero Gears", ...specialSkillHeroNames(grouped.map((c) => c.name))]);
  const GROUPED_CHILDREN = new Set(Object.values(CATEGORY_GROUPS).flat());
  const EXTRA_BUFF_SET = new Set(EXTRA_BUFF_SUBCATS);
  const HIDDEN_BUFF_CATS = new Set(["Chief Bonus", "Charm", "Chief", "Extra Buff", "Buff", "Skins", "Islands", "War Acd.", "Research", "Pets", "Expert", "Exp. Research"]);
  const holder = document.getElementById("dynamicTabs");
  if (holder) {
    holder.innerHTML = BUFF_CATEGORIES.filter(
      (c) => !HERO_SUBCATS.has(c.name) && !GROUPED_CHILDREN.has(c.name) && !EXTRA_BUFF_SET.has(c.name) && !HIDDEN_BUFF_CATS.has(c.name)
    )
      .map((c) => `<button data-tab="buffcat:${esc(c.name)}"><span class="ic">&#9670;</span>${esc(EXTRA_BUFF_LABELS[c.name] || c.name)}</button>`)
      .join("");
  }
  document.querySelectorAll("#tabs button[data-tab]").forEach((b) => {
    b.classList.toggle("active", b.dataset.tab === TAB);
  });
}

// Top-level wrapper for a single buff category page.
async function renderCategoryPage(categoryName) {
  await renderCategoryInto(content, categoryName, renderCategoryPage);
}

// Renders one category's row list (name + value) into any target
// element, with inline add/update controls. Reused by top-level
// category pages, Heroes sub-nav, and grouped sub-nav pages.
async function renderCategoryInto(target, categoryName, rerenderFn) {
  const seq = RENDER_SEQ;
  await ensureBuffTable();
  const cat = BUFF_CATEGORIES.find((c) => c.name === categoryName);
  if (seq !== RENDER_SEQ) return;
  if (!cat) {
    target.innerHTML = `<div class="empty">Category not found.</div>`;
    return;
  }
  // Redrawn after an edit: the page stays where it was.
  const redrawFn = rerenderFn || ((name) => renderCategoryInto(target, name, rerenderFn));
  const refresh = (name) => keepPlace(() => redrawFn(name));
  const rows = await sb(`buff_rows?table_id=eq.${BUFF_TABLE_ID}&select=id,name,sort_order,buff_cells(value,column_id)&order=sort_order.asc`);

  if (seq !== RENDER_SEQ) return;
  target.innerHTML = `
    <div class="panel">
      <h2>${esc(categoryName)}</h2>
      <p class="desc">Values tracked for this category.</p>
      <div id="catRows-${esc(categoryName)}"></div>
      <form class="inline" id="addRowForm-${esc(categoryName)}" style="margin-top:14px; border-top:1px solid var(--line); padding-top:14px;">
        <input class="flex1" name="rowName" placeholder="Add a stat line, e.g. Infantry ATT" />
        <input class="field-num" name="rowValue" type="number" step="any" placeholder="Value" />
        <button class="btn small" type="submit">Add</button>
      </form>
      <div class="err" id="addRowErr-${esc(categoryName)}"></div>
    </div>
  `;

  const rowsEl = target.querySelector(`#catRows-${window.CSS.escape(categoryName)}`);
  const colIds = cat.columns.map((c) => c.id);
  const rowsHtml = rows
    .map((r) => {
      const cellsByCol = Object.fromEntries(r.buff_cells.map((c) => [c.column_id, c.value]));
      const v = colIds.map((id) => cellsByCol[id]).find((x) => x != null);
      return `<div class="row">
        <div class="name">${esc(r.name)}</div>
        <div style="display:flex; align-items:center; gap:10px;">
          <div class="meta mono">${v != null ? Number(v).toLocaleString() : "\u2014"}</div>
          <button class="btn small ghost" data-row="${r.id}" data-val="${v ?? ""}">Update</button>
        </div>
      </div>`;
    })
    .join("");
  rowsEl.innerHTML = rowsHtml || `<div class="empty"><div class="big">No stat lines yet.</div>Add one below.</div>`;

  rowsEl.querySelectorAll("button[data-row]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const val = prompt("Value:", btn.dataset.val);
      if (val === null) return;
      const num = Number(val);
      if (Number.isNaN(num)) { toast("Enter a valid number", true); return; }
      try {
        // Upsert on the (row_id, column_id) unique key, so an existing value
        // is updated instead of the insert being rejected as a duplicate.
        await sb(`buff_cells?on_conflict=row_id,column_id`, {
          method: "POST",
          headers: { Prefer: "resolution=merge-duplicates,return=representation" },
          body: JSON.stringify({ row_id: btn.dataset.row, column_id: cat.columns[0].id, value: num }),
        });
        dropKeptGameData();
        toast("Updated");
        refresh(categoryName);
      } catch (err) {
        toast("Couldn't update value", true);
      }
    });
  });

  target.querySelector(`#addRowForm-${window.CSS.escape(categoryName)}`).addEventListener("submit", async (e) => {
    e.preventDefault();
    const f = e.target;
    const errEl = target.querySelector(`#addRowErr-${window.CSS.escape(categoryName)}`);
    errEl.textContent = "";
    const name = f.rowName.value.trim();
    if (!name) { errEl.textContent = "Enter a stat line name first"; return; }
    const valueRaw = f.rowValue.value.trim();
    try {
      const [rowRow] = await sb(`buff_rows`, {
        method: "POST",
        body: JSON.stringify({ table_id: BUFF_TABLE_ID, name, sort_order: rows.length }),
      });
      if (valueRaw !== "") {
        await sb(`buff_cells`, {
          method: "POST",
          body: JSON.stringify({ row_id: rowRow.id, column_id: cat.columns[0].id, value: Number(valueRaw) }),
        });
      }
      dropKeptGameData();
      toast("Stat line added");
      refresh(categoryName);
    } catch (err) {
      errEl.textContent = "Couldn't add stat line \u2014 name may already exist";
    }
  });
}

// Generic "parent category with sub-tab children" page, e.g.
// War Acd. -> T11/T12. Driven by CATEGORY_GROUPS.
async function renderGroupPage(parentName) {
  const seq = RENDER_SEQ;
  const children = CATEGORY_GROUPS[parentName];
  const subtabs = [parentName, ...children];
  const current = GROUP_SUBTAB[parentName] || parentName;

  content.innerHTML = `
    <div style="display:flex; gap:6px; margin-bottom:16px; flex-wrap:wrap;">
      ${subtabs
        .map(
          (s) =>
            `<button class="btn small ${current === s ? "" : "ghost"}" data-groupsub="${esc(s)}" style="${current === s ? "background:var(--ice-dim); border-color:var(--ice-dim);" : ""}">${esc(s)}</button>`
        )
        .join("")}
    </div>
    <div id="groupSubContent"></div>
  `;
  content.querySelectorAll("[data-groupsub]").forEach((btn) => {
    btn.addEventListener("click", () => {
      GROUP_SUBTAB[parentName] = btn.dataset.groupsub;
      keepPlace(() => renderGroupPage(parentName));
    });
  });

  await ensureBuffTable();
  if (!BUFF_CATEGORIES.some((c) => c.name === current)) {
    await loadBuffCategories();
  }
  if (seq !== RENDER_SEQ) return;
  const sub = document.getElementById("groupSubContent");
  await renderCategoryInto(sub, current, () => renderGroupPage(parentName));
}

