// Fill / handle positions of one row ("from": green fill to the value; "to": the
// Now part faint, then blue to the value).
function enhRowStyle(T, role, val, base) {
  const p = (v) => `${enhPct(T, v).toFixed(2)}%`;
  if (val == null) return { n: "width:0", b: "width:0", t: "width:0", h: "display:none" };
  const b0 = base == null ? 0 : Math.min(base, val);
  return role === "from"
    ? { n: `width:${p(val)}`, h: `left:${p(val)}` }
    : { b: `width:${p(b0)}`, t: `left:${p(b0)};width:calc(${p(val)} - ${p(b0)})`, h: `left:${p(val)}` };
}
// o: { T, rows: [{ role, label, val, base, lo, hi, ghosts }], flags: [{ v, txt, ok }], labOf, hint, note }
function enhGridHtml(o) {
  const p = (v) => `${enhPct(o.T, v).toFixed(2)}%`;
  const notch = o.flags.map((f) => `<i class="eb-n" style="left:${p(f.v)};"></i>`).join("");
  const row = (r) => {
    const st = enhRowStyle(o.T, r.role, r.val, r.base), isT = r.role === "to";
    const fills = isT ? `<i class="hw-f e4-base" data-egf="b" style="${st.b}"></i><i class="hw-f t" data-egf="t" style="${st.t}"></i>` : `<i class="hw-f n" data-egf="n" style="${st.n}"></i>`;
    const ghosts = r.val == null ? [...new Set(r.ghosts || [])].map((v) => `<span class="hw-th ghost${isT ? " t" : ""}" style="left:${p(v)};"></span>`).join("") : "";
    const v = r.val;
    return `<div class="e5-l${isT ? " tgt" : ""}">${esc(r.label)}<b data-egl="${r.role}">${v == null ? "&mdash;" : esc(o.labOf(v))}</b></div>
      <button type="button" class="e4-pm" data-egpm="${r.role}|-1" aria-label="&minus;"${v != null && v <= r.lo ? " disabled" : ""}>&minus;</button>
      <div class="e4-in" data-egbar="${r.role}"><div class="hw-tr2">${fills}${notch}${ghosts}<span class="hw-th ${isT ? "t" : "n"}" data-egh style="${st.h}"></span></div></div>
      <button type="button" class="e4-pm" data-egpm="${r.role}|1" aria-label="+"${v != null && v >= r.hi ? " disabled" : ""}>+</button>`;
  };
  const vals = {}; o.rows.forEach((r) => { vals[r.role] = r.val; });
  const lo = vals.from ?? -1, hi = vals.to ?? -1;
  const fl = o.flags.map((f) => `<span class="hw-fl${f.ok ? " ok" : ""}" style="left:${p(f.v)};">${f.txt}</span>`).join("");
  const msv = new Set(o.flags.map((f) => f.v));
  const tk = o.T.map((v) => `<button type="button" class="hw-tk${v <= lo ? " d" : v <= hi ? " t" : ""}${msv.has(v) ? " ms" : ""}" data-egtk="${v}" style="left:${p(v)};">${esc(o.labOf(v))}</button>`).join("");
  return `<div class="e5-g" data-eg>
    <div></div><div></div><div class="e4-in"><div class="hw-fls">${fl}</div></div><div></div>
    ${o.rows.map(row).join("")}
    <div></div><div></div><div class="e4-in"><div class="hw-tks">${tk}</div></div><div></div></div>${o.note ? `<div class="sal-note">${o.note}</div>` : ""}${o.hint ? `<div class="e4-hint">${esc(o.hint)}</div>` : ""}`;
}
// Paints a grid for new values while a handle is dragged / − + held (no redraw).
function enhPaint(grid, T, vals, labOf) {
  grid.querySelectorAll("[data-egbar]").forEach((bar) => {
    const role = bar.dataset.egbar, v = vals[role];
    if (v === undefined) return;
    const st = enhRowStyle(T, role, v, vals.from);
    bar.querySelectorAll("[data-egf]").forEach((f) => { f.style.cssText = st[f.dataset.egf] || ""; });
    const h = bar.querySelector("[data-egh]"); if (h) h.style.cssText = st.h;
    bar.querySelectorAll(".hw-th.ghost").forEach((g) => { g.style.display = v == null ? "" : "none"; });
    const l = grid.querySelector(`[data-egl="${role}"]`); if (l) l.textContent = v == null ? "—" : labOf(v);
  });
  const lo = vals.from ?? -1, hi = vals.to ?? -1;
  grid.querySelectorAll("[data-egtk]").forEach((b) => { const v = Number(b.dataset.egtk); b.classList.toggle("d", v <= lo); b.classList.toggle("t", v > lo && v <= hi); });
}
// ctl: { T, mem: { last }, val(role), start(role), clamp(role, v), live(role, v), commit(), cancel() }
function wireEnhGrid(grid, ctl) {
  const rows = [...grid.querySelectorAll("[data-egbar]")];
  if (rows.length === 1) ctl.mem.last = rows[0].dataset.egbar;
  rows.forEach((bar) => {
    bar.onpointerdown = (e) => {
      if (!e.isPrimary || (e.pointerType === "mouse" && e.button !== 0)) return;
      const role = bar.dataset.egbar, tr = bar.querySelector(".hw-tr2");
      ctl.mem.last = role;
      const at = (x) => { const r = tr.getBoundingClientRect(); return ctl.clamp(role, enhAt(ctl.T, (x - r.left) / Math.max(1, r.width))); };
      try { bar.setPointerCapture(e.pointerId); } catch (err) { /* old browsers */ }
      bar.classList.add("drag");
      ctl.live(role, at(e.clientX));
      const end = (ok) => {
        bar.onpointermove = bar.onpointerup = bar.onpointercancel = null;
        bar.classList.remove("drag");
        if (ok) ctl.commit(); else ctl.cancel();
      };
      bar.onpointermove = (ev) => ctl.live(role, at(ev.clientX));
      bar.onpointerup = () => end(true);
      bar.onpointercancel = () => end(false);
    };
  });
  grid.querySelectorAll("[data-egtk]").forEach((b) => {
    b.onclick = () => { const role = ctl.mem.last || "to"; ctl.live(role, ctl.clamp(role, Number(b.dataset.egtk))); ctl.commit(); };
  });
  wireHoldStep(grid.querySelectorAll("[data-egpm]"), (b) => {
    const [role, d] = b.dataset.egpm.split("|");
    ctl.mem.last = role;
    const cur = ctl.val(role), nv = ctl.clamp(role, cur == null ? ctl.start(role) : cur + Number(d));
    if (nv === cur) return false;
    ctl.live(role, nv);
    return true;
  }, () => ctl.commit());
}

// Renders the 3-troop-type x 2-piece x 3-charm-slot calculator,
// each slot with its own current\u2192target level pair.
let CHARM_STATE_LOADED = false;
let CHARM_STATE_PROMISE = null;
// Loads any saved Charm selections into CHARM_CALC_STATE. Safe to call
// from anywhere; only fetches once per session. Callers running at the
// same time share one load (so nobody sees the state before the saved
// selections are applied), and a failed load is retried on the next call.
async function ensureCharmData() {
  if (CHARM_STATE_LOADED) return CHARM_STATE_PROMISE;
  CHARM_STATE_LOADED = true;
  CHARM_STATE_PROMISE = loadCharmData().catch((e) => { CHARM_STATE_LOADED = false; throw e; });
  return CHARM_STATE_PROMISE;
}
// A saved level past hidden upcoming levels reads as the last level left.
function charmShownLevel(l) {
  if (CHARM_LEVELS_ALL.length === CHARM_LEVELS.length || CHARM_LEVELS.includes(String(l))) return l;
  return CHARM_LEVELS_ALL.indexOf(String(l)) >= CHARM_LEVELS.length ? CHARM_LEVELS[CHARM_LEVELS.length - 1] : l;
}
async function loadCharmData() {
  await ensureCharmLevelsData();
  const saved = await loadCalcState("charm");
  if (!saved && !IS_OWNER) CHARM_PIECES.forEach((p) => CHARM_CALC_STATE[p.key].forEach((slot) => { slot.target = slot.current; }));
  if (saved) {
    CHARM_PIECES.forEach((p) => {
      if (Array.isArray(saved[p.key])) {
        saved[p.key].forEach((slot, i) => {
          if (CHARM_CALC_STATE[p.key][i] && slot) {
            if (slot.current) CHARM_CALC_STATE[p.key][i].current = charmShownLevel(slot.current);
            if (slot.target) CHARM_CALC_STATE[p.key][i].target = charmShownLevel(slot.target);
          }
        });
      }
    });
  }
}


// ============================================================
// PACKS -> CALCULATOR PAGES
// A pack table can be pointed at one or more calculator pages, and each of
// its columns labelled with the resource it grants (plus which column holds
// the price). Those pages then show what the packs would cost to cover what
// they still need. The links live in calc_state, so no database change is
// needed and they follow the user across devices.
// ============================================================
// "Used for" checkboxes: one tick can cover several pages (Pets, Experts,
// Research), each stored as its own page key so the pages keep working
// independently.
const PACK_PAGE_GROUPS = [
  { key: "chief_gear", pages: ["chief_gear"] },
  { key: "charm", pages: ["charm"] },
  { key: "hero_gear", pages: ["hero_gear"] },
  { key: "pets", pages: ["pets"] },
  { key: "pets_refine", pages: ["pets_refine"] },
  { key: "experts_group", group: "Experts", pages: ["experts", "experts_research"] },
  { key: "research_group", group: "Research", pages: ["research_center", "t11_helios", "t12_research"] },
  // Budgets' "Hero shards & widgets" (old packs that give hero shards).
  { key: "hero_shards", pages: ["hero_shards"] },
  // Islands: packs that give Mark of Revival (Daybreak Island Supply …).
  { key: "islands", pages: ["islands"] },
];
function packGroupLabel(g) {
  if (g.group) { const e = NAV_GROUP_LABELS[g.group]; return e ? (e[LANG] || e.en) : g.group; }
  return packPageLabel(g.pages[0]);
}
// A table ticked for a group (e.g. "Pets") counts for every page in that
// group, even if it was ticked before a page joined the group.
function packTableServesPage(tb, calcKey) {
  // Shining City skins: the packs used for Islands that give Glorious Tomes (Shining City Pack).
  if (calcKey === "shining_skins") return packTableServesPage(tb, "islands") && Object.values(packEffectiveCols(tb)).some((c) => /glorious tome/i.test(String(c)));
  // "My packs" with no "Used for" ticked count for every page (the planner
  // only buys them where their items are needed).
  const own = packLinkFor(tb.id);
  if ((own.mine || (typeof own.group === "string" && own.group.trim() === PACK_MINE_GROUP)) && !(own.pages || []).length) return true;
  const servedBy = (pages) => {
    if (pages.includes(calcKey)) return true;
    const g = packGroupOf(calcKey);
    return !!g && g.pages.some((k) => pages.includes(k));
  };
  const link = packLinkFor(tb.id);
  if (servedBy(link.pages)) return true;
  // A table linked as "same pack" follows its partners onto their pages.
  if (link.linkSet) return packLinkSetMembers(link.linkSet).some((x) => x.id !== tb.id && servedBy(packLinkFor(x.id).pages));
  return false;
}
let PACK_TABLES_ALL = null; // every table, for "same pack" lookups (Packs page keeps it fresh)
function packLinkSetMembers(setId) {
  // (Speed: only the linkSet is read, not every table's whole link - this runs per table per page.)
  return (PACK_TABLES_CACHE || PACK_TABLES_ALL || []).filter((x) => packLinkSetOf(x.id) === setId);
}
// Short tag telling linked tables apart ("Classic" / "Sublime"): the part
// of the title that isn't shared with the others.
function packLinkSetTags(tbs) {
  const titles = tbs.map((x) => String(x.title || "").trim());
  const words = titles.map((x) => x.split(/[\s:·\-()"']+/).filter(Boolean));
  const norm = (w) => w.toLowerCase().replace(/s$/, "");
  // A word every title shares (Chief, Gear/Gears, Artisan's, Trove...) says
  // nothing about which option this is, so it goes; what's left is the tag.
  const shared = new Set((words[0] || []).map(norm).filter((n) => words.every((w) => w.some((x) => norm(x) === n))));
  return words.map((w, i) => {
    const own = w.filter((x) => !shared.has(norm(x)));
    return (own.length ? own.join(" ") : titles[i] || `#${i + 1}`).slice(0, 20);
  });
}
function packGroupOf(pageKey) {
  return PACK_PAGE_GROUPS.find((g) => g.pages.includes(pageKey));
}
function packPageLabel(key) {
  if (key === "hero_shards") return t("hs_page");
  if (key === "islands") { const e = NAV_PAGE_LABELS.islandgallery; return e ? (e[LANG] || e.en) : "Islands"; }
  if (key === "shining_skins") return t("isl_sc_name");
  const entry = NAV_PAGE_LABELS[{ chief_gear: "chiefgear", charm: "charmscalc", hero_gear: "herogearcalc", research_center: "researchcenter", t11_helios: "t11helios", t12_research: "t12research", pets: "petsdata", pets_refine: "refinepage", experts: "expertspage", experts_research: "expertsresearchpage" }[key]];
  return entry ? (entry[LANG] || entry.en) : key;
}
