    const nextTxt = nd == null ? "" : [byDay.get(nd).some((x) => x.kind === "hero") ? t("tl_gen_heroes").replace("{g}", genAt.get(nd) || genOf(nd)) : "", ...nextNames].filter(Boolean).join(" + ");
