// ---- Game events: SvS and King of Icefield (KOI) ----
// Each comes every 4 weeks for 6 days (Monday to Saturday); the Lucky Wheel
// (heroes) opens on day 2 and stays 3 days. SvS 5-10 Oct 2026 and KOI
// 21-26 Sep 2026 were seen in game (set here by the admin, used only to
// work out the New Gen Heroes dates and shown on the calendar).
const GAME_EVENTS = [
  { key: "svs", name: "SvS", anchor: "2026-10-05", every: 28, days: 6, wheelDay: 2, wheelDays: 3 },
  { key: "koi", name: "KOI", anchor: "2026-09-21", every: 28, days: 6, wheelDay: 2, wheelDays: 3 },
];
// Start days of an event from `from` to `to` (Dates).
function gameEventAnchor(ev) { return ev.anchor; }
function gameEventStarts(ev, from, to) {
  const a = packParseDay(gameEventAnchor(ev)), step = ev.every * 86400000, out = [];
  let k = Math.floor((from - a) / step) - 1;
  for (;; k++) { const d = new Date(a.getTime() + k * step); if (d > to) break; if (d.getTime() + (ev.days - 1) * 86400000 >= from.getTime()) out.push(d); }
  return out;
}
// Hero wheels between two days: [{ day, ev, start }], in order.
function heroWheels(from, to) {
  const out = [];
  GAME_EVENTS.forEach((ev) => gameEventStarts(ev, new Date(from.getTime() - 7 * 86400000), to).forEach((st) => {
    const day = new Date(st.getTime() + (ev.wheelDay - 1) * 86400000);
    if (day >= from && day <= to) out.push({ day, ev, start: st });
  }));
  return out.sort((a, b) => a.day - b.day);
}
// New Gen Heroes: a generation lasts at least 80 days AND until 5 Lucky
// Wheels (SvS or KOI) including 3 SvS ones have opened; the new heroes come
// the first Monday when all three are true. Returns the start days from
// `lastKey` on.
const NEW_GEN_MEMO = new Map(); // packLinkFor asks often; same inputs, same answer
function newGenStarts(lastKey, count) {
  const mk = [lastKey, count, ...GAME_EVENTS.map(gameEventAnchor)].join("|");
  if (NEW_GEN_MEMO.has(mk)) return NEW_GEN_MEMO.get(mk).slice();
  const res = newGenStartsCompute(lastKey, count);
  if (NEW_GEN_MEMO.size > 50) NEW_GEN_MEMO.clear();
  NEW_GEN_MEMO.set(mk, res);
  return res.slice();
}
function newGenStartsCompute(lastKey, count) {
  let cur = packParseDay(lastKey);
  if (!cur) return [];
  const out = [cur];
  while (out.length < count) {
    const ws = heroWheels(new Date(cur.getTime() + 86400000), new Date(cur.getTime() + 300 * 86400000));
    let n = 0, svs = 0, hit = null;
    for (const w of ws) { n++; if (w.ev.key === "svs") svs++; if (n >= NEW_GEN_WHEELS && svs >= NEW_GEN_SVS) { hit = w; break; } }
    if (!hit) break;
    // The Monday after that wheel's event week, and not before 80 days.
    let next = new Date(hit.start.getTime() + 7 * 86400000);
    next = new Date(next.getTime() - ((next.getUTCDay() + 6) % 7) * 86400000);
    const min = new Date(cur.getTime() + NEW_GEN_MIN_DAYS * 86400000);
    if (next < min) next = new Date(min.getTime() + ((8 - min.getUTCDay()) % 7) * 86400000);
    cur = next;
    out.push(cur);
  }
  return out;
}
