const PACK_COST_VIEW = {};
// Which view the Pack cost box opens on (the switch still changes it):
// it opens on "This page only" for everyone; the switch shows the shared plan.
function packCostDefaultView() { return "page"; }
const PACK_VIEW_TOTALS = {};   // per page: last known totals of both views, for the switch labels     // per page: "shared" | "page" (this session)     // per page; hidden on every load until opened
const PACK_TARGET_CACHE = {};  // per page target date (ISO yyyy-mm-dd), from calc_state
// The Pack cost block is owner-only on every page.
const PACK_COST_GEN = {};      // per page: bumps on every re-render request
async function renderPackCostBlock(containerEl, calcKey, groups, owned) {
  if (!containerEl) return;
  const gen = (PACK_COST_GEN[calcKey] = (PACK_COST_GEN[calcKey] || 0) + 1);
  const stale = () => PACK_COST_GEN[calcKey] !== gen || !containerEl.isConnected;
  if (!visitorCan("packcost")) { containerEl.innerHTML = ""; return; }
  await ensurePackLinks();
  const tables = (await ensurePackTables()).filter((tb) => packTableServesPage(tb, calcKey));
  if (!tables.length) { containerEl.innerHTML = ""; return; }
  const ownedOrig = owned;
  const activeCards = packActiveCardSupply(calcKey, tables);
  if (activeCards.used.length) owned = packMergeOwned(owned, activeCards.supply);
  if (PACK_TARGET_CACHE[calcKey] === undefined) {
    const saved = await loadCalcState(`pack_target_${calcKey}`);
    PACK_TARGET_CACHE[calcKey] = (saved && typeof saved.date === "string") ? saved.date : "";
  }
  const targetDate = PACK_TARGET_CACHE[calcKey];
  const open = PACK_COST_OPEN[calcKey] === true;

  const rerender = () => renderPackCostBlock(containerEl, calcKey, groups, ownedOrig);
  // Card layout (design A, every page): plans as cards to pick from, then
  // the picked plan's packs as a short list.
  let aBuilt = false;
  const wrapOpen = `<div class="pc-card pca">`;
  const head = `
    <div class="pc-head">
      <button type="button" data-packtoggle class="pc-title">${esc(t("pc_title"))} ${open ? "&#9662;" : "&#9656;"}</button>
    </div>`;

  if (!open) {
    packCostShown(calcKey, null);
    containerEl.style.minHeight = "";
    containerEl.innerHTML = `${wrapOpen}${head}</div>`;
    containerEl.querySelector("[data-packtoggle]").addEventListener("click", () => { PACK_COST_OPEN[calcKey] = true; rerender(); });
    return;
  }

  // Changing several levels in a row: wait until the changes stop, so the
  // plan is worked out once for the final numbers instead of after every click.
  // The card keeps its height meanwhile (it sits low on phones: a short
  // "Working out…" would pull the page up).
  if (containerEl.offsetHeight) containerEl.style.minHeight = containerEl.offsetHeight + "px";
  containerEl.innerHTML = `${wrapOpen}${head}<div class="meta" style="font-size:11px; margin-top:8px; padding:8px 10px; border:1px dashed var(--line); border-radius:8px;"><b style="color:var(--ice);">${esc(t("budgets_loading"))}</b><br>${esc(t("pack_calc_wait"))}</div></div>`;
  await new Promise((r) => setTimeout(r, 450));
  if (stale()) return;
  // What this page needs in total, across every group (e.g. all 3 Hero Gear sets).
  const needFull = {};
  groups.forEach((g) => Object.entries(g.totals || {}).forEach(([name, qty]) => {
    needFull[name] = (needFull[name] || 0) + (Number(qty) || 0);
  }));
  const needStill = {};
  Object.keys(needFull).forEach((name) => {
    needStill[name] = Math.max(0, needFull[name] - (Number((owned || {})[name]) || 0));
  });
  // Pack cost always prices what's still needed.
  PACK_COST_MODE = "still";
  // Days until the target date (today counts as day 0), on the game's (UTC) days.
  const today = packStartOfToday();
  let targetDays = null;
  if (targetDate) {
    const d = packParseDay(targetDate);
    if (d) targetDays = Math.round((d - today) / 86400000);
  }
  // Spare items traded into missing ones first, when trades are switched on
  // (weekly trade limits scale with the weeks left until the target).
  await ensureTradeRates();
  const traded = PACK_COST_MODE === "still" ? tradeAdjustedStill(calcKey, needFull, owned, targetDays, true) : null;
  // The free trades with their weekly limit (split this week / next weeks like the Backpack box pop-ups).
  const tradeRates = tradeRatesFor(calcKey);
  const freeTrades = traded ? traded.trades.map((x) => { const r = tradeRates.find((q) => q.from === x.from && q.to === x.to) || {}; return { ...x, max: Number(r.max) || 0, wk1: r.wk1, hidden: !!r.hidden }; }) : [];
  const base = PACK_COST_MODE === "full" ? needFull : (traded ? traded.still : needStill);
  const packGroups = packGroupsFor(tables, calcKey);
  const supplied = new Set();
  tables.forEach((tb) => Object.values(packEffectiveCols(tb)).forEach((r) => { if (r === "Gems" && !packGemsCountFor(calcKey)) return; Object.keys(packBundleContents(r)).forEach((n) => supplied.add(n)); }));
  const viaTrades = packNeedViaTrades(calcKey, base, supplied, targetDays);
  packSplitUncoverable(packGroups, viaTrades, calcKey);
  const need = viaTrades.need;

  const fmtDate = (days) => {
    const d = new Date(today.getTime() + days * 86400000);
    try { return d.toLocaleDateString(LANG === "en" ? undefined : LANG, { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" }); } catch (e) { return d.toDateString(); }
  };
  const qty = (v) => Math.round(v).toLocaleString();
  const currency = (packGroups[0] && packGroups[0].offers[0].currency) || "USD";
  const resetText = (r, day) => {
    if (r === "unlimited") return t("pack_reset_unlimited");
    if (r === "once" || r >= PACK_ONE_TIME_DAYS) return t("pack_reset_once");
    if (packStackInfo(r)) return packStackText(r);
    const preset = PACK_RESET_PRESETS.find((p) => p.days === r);
    const base = preset ? t("pack_reset_" + preset.key) : `${t("pack_reset_every")} ${r}${t("pack_days_short")}`;
    const next = packResetOffsets(r, day, PACK_HORIZON_DAYS)[0];
    return next == null ? base : `${base} · ${t("pack_next_on")} ${fmtDate(next)}`;
  };

  const targetHtml = `
    <div class="pc-target" style="display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin:8px 0;">
      <span class="meta" style="font-size:11px; font-weight:600;">${esc(t("pack_target_by"))}</span>
      <input type="date" data-packtarget value="${esc(targetDate)}" style="font-size:12px; padding:4px 6px;" />
      ${targetDate ? `<button type="button" class="btn small ghost" data-packtargetclear title="${esc(t("pack_no_date"))}" style="padding:2px 8px;">&times;</button>` : `<span class="meta" style="font-size:10.5px;">${esc(t("pack_no_date"))}</span>`}
      ${targetDays != null ? `<span class="meta" style="font-size:11px; color:${targetDays < 0 ? "var(--danger)" : "var(--ice)"};">${targetDays < 0 ? esc(t("pack_overdue")) : `${targetDays} ${esc(t("pack_days_left"))}`}</span>` : ""}
    </div>`;

  let sections;
  // Items no pack setup can cover (listed, not planned).
  const uncoveredHtml = Object.keys(viaTrades.uncovered).length ? `<div class="meta" style="font-size:10.5px; margin:6px 0; padding:6px 8px; border:1px solid var(--danger); border-radius:8px; color:var(--danger);">${esc(t("pack_cant_cover"))}: ${Object.keys(viaTrades.uncovered).map((n) => `<b>${esc(materialDisplayName(n))} ${qty(viaTrades.uncovered[n])}</b>${viaTrades.maxWithin && viaTrades.maxWithin[n] != null ? ` <span class="meta">(${esc(t("pack_max_3y"))} ${qty(viaTrades.maxWithin[n])})</span>` : ""}`).join(" &middot; ")}<br><span class="meta" style="color:var(--muted);">${esc(t("pack_uncovered_hint"))}</span></div>` : "";
  // Shared packs: show this page's share of the combined Budgets plan.
  let shared = null;
  if (PACK_COST_MODE === "still") {
    // The combined plan can take a couple of seconds: say so and let the
    // page paint before the work starts, instead of looking frozen.
    // Only the view that's showing is worked out; the other one's total is
    // shown on its button when it's already known for these same numbers.
    let info = null;
    // Everyone gets both views (the switch). The box opens on "This page
    // only"; the shared plan is only worked out when "Shared" is tapped.
    try { info = await budgetCombinedFor(calcKey, groups, { infoOnly: true }); } catch (e) { info = null; }
    if (info && info.notIncluded) shared = info;
    else if (info && (PACK_COST_VIEW[calcKey] || packCostDefaultView()) === "shared") {
      try { shared = await budgetCombinedFor(calcKey, groups); } catch (e) { console.error("combined plan failed", e); shared = null; }
    } else if (info) shared = { lazyShare: true, sharedWith: info.sharedWith };
    if (stale()) return;
  }
  const sharedNote = (msg) => `<div class="meta" style="font-size:10.5px; margin:6px 0; padding:6px 8px; border:1px solid var(--line); border-radius:8px;">${esc(msg)}</div>`;
  // Design A rows: one row per pack with its main item's
  // picture, real name (the table name, not its option list), how often it
  // comes back, what it gives (needed items first) and its price; tap = its steps.
  const pcaIcon = (n) => { const src = materialIconSrc(n); return src ? `<img src="${esc(src)}" alt="" loading="lazy" />` : ""; };
  const pcaCur = (v) => String(v).replace(/^([\u2066\u200e\u200f]*)([^\d\s\-\u2066-\u2069\u200e\u200f]+)\s?/, '$1<small class="cur">$2</small> ');
  // (Pet Refine: Advanced Marks count as Common ones, so they are needed too.)
  const pcaNeeded = (n) => (Number(need[n]) || 0) > 0 || (n === "Advanced Marks" && (Number(need["Common Marks"]) || 0) > 0);
  // Pet Refine: packs where you pick Common or Advanced Marks in the game ("Buy the marks as").
  const mkTables = calcKey === "pets_refine" ? packMarksChoiceTables(tables) : [];
  const mkIds = new Set(mkTables.map((tb) => String(tb.id)));
  const mkNote = (g) => (mkIds.size && g.lines.some((r) => (r.tables || []).some((id) => mkIds.has(String(id)))) ? t("pca_mk_game").replace("{m}", t(petMarksBuyAs() === "common" ? "pca_mk_com" : "pca_mk_adv")) : "");
  const pcaRows = (byPack, rowsAll, priceOf, noteOf) => {
    const all = {};
    rowsAll.forEach((r) => Object.entries(r.gives || {}).forEach(([n, q]) => { all[n] = (all[n] || 0) + (Number(q) || 0) * r.count; }));
    return byPack.slice().sort((a, b) => b.subtotal - a.subtotal).map((g) => {
      const gv = {};
      g.lines.forEach((r) => Object.entries(r.gives || {}).forEach(([n, q]) => { gv[n] = (gv[n] || 0) + (Number(q) || 0) * r.count; }));
      // Pet Refine, bought as Advanced: the plan counts them as Common (1 = 8); show the Advanced ones.
      if (mkNote(g) && petMarksBuyAs() === "adv" && gv["Common Marks"] > 0) {
        gv["Advanced Marks"] = (gv["Advanced Marks"] || 0) + gv["Common Marks"] / ADVANCED_MARK_VALUE;
        all["Advanced Marks"] = (all["Advanced Marks"] || 0) + gv["Common Marks"] / ADVANCED_MARK_VALUE;
        delete gv["Common Marks"];
      }
      const share = (n) => gv[n] / (all[n] || 1);
      const items = Object.keys(gv).filter((n) => gv[n] > 0 && n !== "Gems");
      const pool = items.filter(pcaNeeded).length ? items.filter(pcaNeeded) : items;
      const main = pool.slice().sort((a, b) => share(b) - share(a))[0];
      const chips = items.sort((a, b) => (pcaNeeded(b) - pcaNeeded(a)) || share(b) - share(a)).slice(0, 4);
      const parts = String(g.title).split(" \u00b7 "), name = parts.length >= 2 ? parts[1] : parts[0];
      // (A run's left-over steps are a one-off group: say how often the pack itself comes back.)
      const rr = g.lines.find((r) => typeof r.reset === "number" && r.reset < PACK_ONE_TIME_DAYS);
      if (rr && typeof g.reset === "number" && g.reset >= PACK_ONE_TIME_DAYS) { g = { ...g, reset: rr.reset, resetDay: rr.resetDay }; }
      const every0 = typeof g.reset === "number" && !packStackInfo(g.reset) ? resetText(g.reset, g.resetDay).split(" \u00b7 ")[0] : packStackInfo(g.reset) ? t("pc_card_days").replace("{n}", packStackInfo(g.reset).days || 7) : "";
      const every = [every0, mkNote(g)].filter(Boolean).join(" \u00b7 ");
      return `<details class="pca-pk"><summary><span class="pca-pic">${main ? pcaIcon(main) : ""}</span><span class="pca-mid"><span class="pca-nm">${esc(name)} <small>&times;${qty(g.count)}</small></span>${every ? `<span class="pca-sb">${esc(every)}</span>` : ""}${chips.length ? `<span class="pca-gv">${chips.map((n) => `<span class="pca-chip${pcaNeeded(n) ? "" : " x"}" title="${esc(materialDisplayName(n))}">${pcaIcon(n)}+${esc(shortAmount(gv[n]))}</span>`).join("")}</span>` : ""}</span><b class="pca-pr">${pcaCur(packFmtLocal(g.subtotal, g.currency, false, g.sample))}</b></summary>
        <div class="pc-lines">${g.lines.slice().sort((a, b) => b.count - a.count).map((r) => `<div><span>${qty(r.count)}&times;</span><span>${esc(r.label)}${noteOf ? noteOf(r) : ""}</span><span class="meta">${packFmtLocal(priceOf(r), r.currency, false, r.price)}</span></div>`).join("")}</div></details>`;
    }).join("");
  };
  // Free trades counted before buying, one row each, by when they happen (like the box pop-up).
  const freeParts = freeTrades.flatMap(packTradeWhenSplit).sort((a, b) => (a.when === "week" ? 0 : 1) - (b.when === "week" ? 0 : 1));
  // One "⇄ Trades · N" card before "What to buy" with every trade: the free ones (this week /
  // next weeks, packTradeWhenSplit) and the pack plan's own (after the pack), grouped by a
  // small chip. Hide ▴ / Show ▾ (g1-fold) folds it to one line with the counts; kept per page
  // in calc_state bar_hidden ("pc:trades:<calcKey>"). No trades: no card.
  const tradesCard = (planTrades) => {
    // The Research Lab (planned by the pack planner, one refining week a lot): this week's
    // lot, then the next weeks', each listed once.
    const labParts = (planTrades || []).filter((x) => x.lab && x.giveQty > 0).flatMap((x) => packTradeWhenSplit({ ...x, max: 1 }));
    const groups = [
      ["week", [...freeParts.filter((x) => x.when === "week"), ...labParts.filter((x) => x.when === "week")]],
      ["plan", (planTrades || []).filter((x) => x.giveQty > 0 && !x.lab).map((x) => ({ from: x.from, to: x.to, give: x.giveQty, get: x.getQty, lab: x.lab, lots: x.lots }))],
      ["later", [...freeParts.filter((x) => x.when === "later"), ...labParts.filter((x) => x.when === "later")]],
    ].filter(([, a]) => a.length);
    const n = groups.reduce((a, [, r]) => a + r.length, 0);
    if (!n) return "";
    const fk = `pc:trades:${calcKey}`, folded = BAR_SHOW_ALL[fk] === false;
    const row = (x) => `<div class="pca-tr" title="${esc(`${materialDisplayName(x.from)} \u2192 ${materialDisplayName(x.to)}`)}">${pcaIcon(x.from)}<b>${qty(x.give)}</b><span class="pca-ar">&rarr;</span>${pcaIcon(x.to)}<b class="g">${qty(x.get)}</b>${x.lab ? ` <small class="meta">(${esc(t("rfc_title"))}${x.when === "later" ? `, ${x.lots} ${esc(t("rfc_weeks"))}` : ""})</small>` : ""}</div>`;
    const counts = groups.map(([k, r]) => t(`pca_trn_${k}`).replace("{n}", r.length)).join(" \u00b7 ");
    return `<div class="pca-tc${folded ? " g1-folded" : ""}"><div class="pca-tch"><span>&#8644; ${esc(t("pca_trades"))}</span><span class="pca-tcn op">&middot; ${n}</span><span class="pca-tcn fd">&middot; ${esc(counts)}</span><button type="button" class="g1-fold" data-g1fold="${esc(fk)}" aria-expanded="${!folded}">${esc(t(folded ? "g1_show" : "g1_hide"))} ${folded ? "&#9662;" : "&#9652;"}</button></div>
      <div class="pca-tcb">${groups.map(([k, r]) => `<span class="pca-wk ${k}">${esc(t(`pca_tr_${k}`))}</span>${r.map(row).join("")}`).join("")}</div></div>`;
  };
  // Islands: packs that give Mythic Island Shards (Myriad Bazaar steps) can
  // stand in for Marks / Tomes (hidden trades, islShardTradesNow). Listed
  // greyed when the plan doesn't use them ("Checked, not cheaper", their real
  // price with every earlier step), and free when another page buys them.
  const islShardOn = calcKey === "islands" && tradeRatesFor("islands").some((r) => r.islFree);
  const SHI = typeof ISL_SHARD_ITEM !== "undefined" ? ISL_SHARD_ITEM : "Mythic Island Shards";
  const islPc = Number(ISL_RULES.perCopy) || 10;
  const shardsOf = (r) => (Number((r.gives || {})[SHI]) || 0) * (r.count || 1);
  // What one copy costs with Marks (or Tomes) in a plan: its Mark / Tome rows' price per copy.
  const islCopyCost = (rows) => {
    const by = (item, per) => { let cost = 0, q = 0; (rows || []).forEach((r) => { const g = Number((r.gives || {})[item]) || 0; if (g > 0) { cost += packRowLocal(r); q += g * r.count; } }); return q > 0 ? cost / (q / per) : null; };
    const mk = by("Mark of Revival", Number(ISL_RULES.markPrice) || 250);
    if (mk != null) return mk;
    const u = typeof ISL_UNIT !== "undefined" && ISL_UNIT ? ISL_UNIT : {};
    return u.mark != null ? u.mark * (Number(ISL_RULES.markPrice) || 250) : null;
  };
  // Each shard pack's cheapest buy per copy, from the planner's own pack groups (so a
  // run bought part way offers only its later steps, and a used-up run its next one).
  const islShardPacks = () => {
    const out = new Map();
    packGroups.forEach((g) => {
      const offs = typeof g.reset === "number" && g.reset > 0 ? packResetOffsets(g.reset, g.resetDay, PACK_HORIZON_DAYS, g.window) : [0];
      const firstFree = offs.find((o) => !(o === 0 && (g.usedNow || 0) >= (g.perCycle || 1)));
      if (firstFree == null) return;
      g.offers.forEach((o) => {
        const sh = Number(o.gives[SHI]) || 0;
        if (!(sh > 0)) return;
        const loc = packConvert(o.price, o.currency).n, per = loc / (sh / islPc);
        const key = o.tableTitle || "";
        const cur = out.get(key);
        if (!cur || per < cur.per) out.set(key, { title: o.tableTitle || "", label: o.label || "", o, g, price: loc, sample: o.price, currency: o.currency, shards: sh, gives: { ...o.gives }, per, off: firstFree, window: Number(g.window) || 0, part: o.from != null });
      });
    });
    return [...out.values()];
  };
  const islCheckedHtml = (rows) => {
    // Only when copies are being bought (Marks / Tomes needed) and no shard pack is in the plan.
    if (!islShardOn || !((Number(need["Mark of Revival"]) || 0) + (Number(need["Glorious Tome"]) || 0) > 0) || (rows || []).some((r) => shardsOf(r) > 0)) return "";
    const list = islShardPacks();
    if (!list.length) return "";
    const mk = islCopyCost(rows), cheapest = list.slice().sort((a, b) => a.per - b.per)[0];
    const fmt = (v, x) => packFmtLocal(Math.round(v), x.currency, true, x.sample);
    const dayTxt = (off) => { const d = new Date(today.getTime() + off * 86400000); try { return d.toLocaleDateString(LANG === "en" ? undefined : LANG, { day: "numeric", month: "short", timeZone: "UTC" }); } catch (e) { return fmtDate(off); } };
    const when = (x) => (x.off === 0 ? t("pca_ends").replace("{d}", dayTxt(Math.max(0, (x.window || 1) - 1))) : t("pca_next").replace("{d}", dayTxt(x.off)));
    const rowsH = list.sort((a, b) => a.per - b.per).map((x) => {
      const items = Object.keys(x.gives).filter((k) => x.gives[k] > 0 && k !== "Gems").sort((a, b) => (b === SHI) - (a === SHI) || (pcaNeeded(b) - pcaNeeded(a))).slice(0, 4);
      const parts = String(x.title).split(" \u00b7 "), name = parts.length >= 2 ? parts[1] : parts[0];
      return `<div class="pca-pk pca-off"><div class="pca-row"><span class="pca-pic">${pcaIcon(SHI)}</span><span class="pca-mid"><span class="pca-nm">${esc(name)}</span><span class="pca-sb">${esc(x.label.length > 60 ? t("pca_steps").replace("{n}", x.o.tiers || 1) : x.label)} &middot; ${esc(when(x))}</span><span class="pca-gv">${items.map((k) => `<span class="pca-chip${k === SHI ? "" : " x"}" title="${esc(materialDisplayName(k))}">${pcaIcon(k)}+${esc(shortAmount(x.gives[k]))}</span>`).join("")}</span></span><b class="pca-pr">${pcaCur(fmt(x.price, x))}</b></div></div>`;
    }).join("");
    const note = mk != null ? `<div class="pca-note">${esc(t("pca_shard_note").replace("{a}", fmt(cheapest.per, cheapest)).replace("{b}", fmt(mk, cheapest)))}</div>` : "";
    return `<div class="pca-h">${esc(t("pca_not_cheaper"))}</div>${rowsH}${note}`;
  };
  // Islands: shards that pay building copies directly (not a trade in the game).
  const islCopiesLine = (pl) => {
    const n = calcKey === "islands" && pl ? Math.round(Number(pl.islShards) || 0) : 0;
    return n > 0 ? `<div class="pca-bonus">${pcaIcon(SHI)}<span>${esc(t("pca_isl_copies").replace("{n}", qty(n)).replace("{c}", qty(Math.floor(n / islPc))))}</span></div>` : "";
  };
  let sharedSections = null, sharedTotalText = "", pageTotalText = "";
  let pickedTotalText = ""; // the picked plan's total (Fastest / By target / Cheapest)
  // The shared view looks like "This page only": plan cards on top (this
  // page's share, and the whole plan → Budgets), then one folding row per
  // pack with this page's part of its price.
  if (shared && shared.combined && shared.included && shared.combined.chosen && shared.sharedWith.length) {
    const cb = shared.combined, p = cb.chosen, mineShare = cb.shares[calcKey] || { total: 0, rows: [] };
    sharedTotalText = packFmtLocal(Math.ceil(packSharesLocal(mineShare)), p.rows[0]?.currency || currency, true, p.rows[0]?.price);
    const cur = p.rows[0]?.currency || currency, price0 = p.rows[0]?.price;
    const late = shared.targetDays != null && p.days > shared.targetDays;
    const d = new Date(today.getTime() + p.days * 86400000);
    let short; try { short = d.toLocaleDateString(LANG === "en" ? undefined : LANG, { day: "numeric", month: "short", timeZone: "UTC" }) + packYearMark(d); } catch (e) { short = fmtDate(p.days); }
    const whenTxt = p.days === 0 ? t("pack_ready_now") : `${short} · ${p.days}d`;
    const big = (n) => String(packFmtLocal(Math.ceil(n), cur, true, price0)).replace(/^([\u2066\u200e\u200f]*)([^\d\s\-\u2066-\u2069\u200e\u200f]+)\s?/, '$1<small class="cur">$2</small>');
    const byPack = [];
    mineShare.rows.forEach((r) => {
      let g = byPack.find((x) => x.title === r.title);
      if (!g) { g = { title: r.title, count: 0, subtotal: 0, currency: r.currency, reset: r.reset, resetDay: r.resetDay, lines: [] }; byPack.push(g); }
      g.count += r.count; g.subtotal += packShareLocal(r); g.sample = g.sample || r.price; g.lines.push(r);
    });
    const needKeys = new Set(Object.keys(need));
    const trades = (p.trades || []).filter((x) => needKeys.has(x.to));
    // Islands: shard steps the plan buys for other pages pay copies for free.
    let inPlanHtml = "";
    if (islShardOn) {
      let left = (Number(p.islShards) || 0) + (Number(need[SHI]) || 0);
      const mineKeys = new Set(mineShare.rows.map((r) => `${r.title}|${r.label}`));
      const free = left > 0 ? p.rows.filter((r) => shardsOf(r) > 0 && !mineKeys.has(`${r.title}|${r.label}`)) : [];
      let got = 0;
      const lines = free.map((r) => {
        const n = Math.min(left, shardsOf(r));
        if (!(n > 0)) return "";
        left -= n; got += n;
        const pages = Object.keys(cb.shares || {}).filter((k) => k !== calcKey && (cb.shares[k].rows || []).some((x) => x.title === r.title && x.label === r.label)).map(packPageLabel);
        const parts = String(r.title).split(" \u00b7 "), name = parts.length >= 2 ? parts[1] : parts[0];
        return `<div class="pca-pk"><div class="pca-row"><span class="pca-pic">${pcaIcon(SHI)}</span><span class="pca-mid"><span class="pca-nm">${esc(name)} <small>&middot; ${esc(String(r.label).length > 40 ? t("pca_steps").replace("{n}", String(r.label).split(" \u00b7 ").length) : r.label)}</small></span><span class="pca-sb">${pcaCur(packFmtLocal(packRowLocal(r), r.currency, false, r.price))}${pages.length ? ` &middot; ${esc(t("pca_bought_for").replace("{p}", pages.join(", ")))}` : ""}</span><span class="pca-gv"><span class="pca-chip">${pcaIcon(SHI)}${esc(t("pca_for_isl").replace("{n}", qty(n)))}</span></span></span></div></div>`;
      }).join("");
      if (got > 0) inPlanHtml = `<div class="pca-h">${esc(t("pca_in_plan"))}</div>${lines}<div class="pca-note ok">&#10003; ${esc(t("pca_free_shards").replace("{n}", qty(got)).replace("{c}", qty(Math.floor(got / islPc))))}</div>`;
    }
    const sharedFree = tradesCard(trades);
    sharedSections = `<div class="pc-plans">
        <div class="pc-plan on" style="cursor:default;"><div class="pc-k">${esc(t("combined_share"))}</div><b>${big(packSharesLocal(mineShare))}</b><small style="${late ? "color:var(--danger);" : ""}">${esc(whenTxt)}</small></div>
        <button type="button" class="pc-plan" data-gotobudgets title="${esc(t("combined_desc").replace("{pages}", shared.sharedWith.map(packPageLabel).join(", ")))}"><div class="pc-k">${esc(t("pc_all_pages"))}</div><b>${big(packPlanLocal(p))}</b><small>${esc(t("budgets_title"))} &rarr;</small></button>
      </div>
      <div class="pc-list">${sharedFree}${inPlanHtml}${mineShare.rows.length ? `<div class="pca-h">${esc(t("pca_buy"))}</div>${pcaRows(byPack, mineShare.rows, packShareLocal, (r) => (r.share < 0.995 ? ` <small class="meta">(${esc(t("combined_part"))} ${Math.round(r.share * 100)}%)</small>` : ""))}` : `<div class="meta" style="font-size:11px;">${esc(t("combined_no_share"))}</div>`}${islCopiesLine(p)}</div>`;
  }
  const viewSig = `${JSON.stringify(need)}|${targetDate}|${BUDGET_TARGET || ""}|${JSON.stringify(BUDGET_SELECTED || {})}`;
  const skipPagePlan = !!sharedSections;
  if (!packGroups.length) {
    sections = `<div class="meta" style="font-size:11px; margin-top:8px;">${esc(t("pack_no_columns"))}</div>`;
  } else if (!Object.keys(need).length) {
    sections = Object.keys(viaTrades.uncovered).length ? "" : `<div class="meta" style="font-size:11px; margin-top:8px; color:var(--good);">${esc(t("pack_nothing_needed"))}</div>
      ${freeParts.length ? `<div class="pc-list">${tradesCard([])}</div>` : ""}`;
  } else if (skipPagePlan) {
    sections = "";
  } else {
    // Worked out in the background planner (the page stays responsive).
    const pp = await plannerRun("page", { groups: packGroups, need, calcKey, targetDays });
    if (stale()) return;
    const earliest = pp.earliest;
    // Pages whose needs shrink with time (free income up to the date): Cheapest tries later
    // dates, each with the need left by then, and keeps the cheapest plan that makes its date.
    let cheapAt = null;
    const byDate = PACK_NEED_BY_DATE[calcKey];
    if (byDate && earliest != null && targetDays == null) {
      // (Like every page's Cheapest: at most a year after the fastest date.)
      const cands = [...new Set([earliest, earliest + 28, 91, 182, 273, 365, earliest + 365].filter((d) => d >= earliest && d <= Math.min(PACK_HORIZON_DAYS, earliest + 365)))].sort((a, b) => a - b);
      for (const d of cands) {
        const r = byDate(d);
        if (!r || !r.ok) continue;
        const st = {};
        Object.keys(r.totals).forEach((n) => { const v = Math.max(0, r.totals[n] - (Number((owned || {})[n]) || 0)); if (v > 0) st[n] = v; });
        const nd = packNeedViaTrades(calcKey, st, supplied, d).need;
        let plan = null;
        if (!Object.keys(nd).length) plan = { rows: [], total: 0, days: 0, trades: [] };
        else { const q = await plannerRun("page", { groups: packGroups, need: nd, calcKey, targetDays: d }); if (stale()) return; plan = q.byTarget || null; }
        // Done on that date (free income brings the rest by then), not when the last pack is bought.
        if (plan && plan.days <= d && (!cheapAt || packPlanLocal(plan) < packPlanLocal(cheapAt.plan) - 0.005)) cheapAt = { plan: { ...plan, days: d }, d };
      }
      if (cheapAt && pp.cheapest && packPlanLocal(cheapAt.plan) >= packPlanLocal(pp.cheapest)) cheapAt = null;
      if (cheapAt) pp.cheapest = cheapAt.plan;
    }
    const plans = [];
    if (earliest == null) {
      // Explain what's short and how much the packs could give at most,
      // plus which tables limit it (once-only / per-row max).
      const sup = packMaxSupply(packGroups, PACK_HORIZON_DAYS);
      const short = {};
      Object.keys(need).forEach((n) => { if ((sup[n] || 0) < need[n]) short[n] = need[n] - (sup[n] || 0); });
      const limited = tables.filter((tb) => { const l = packLinkFor(tb.id); return l.reset === "once" || Object.keys(l.rowMax || {}).length; }).map((tb) => tb.title || t("packs_title"));
      const shortHtml = Object.keys(short).length
        ? Object.keys(short).map((n) => `${esc(materialDisplayName(n))} ${qty(short[n])} <span class="meta">(${esc(t("pack_max_supply"))} ${qty(sup[n] || 0)} / ${qty(need[n])})</span>`).join(" &middot; ")
        : esc(t("pack_cant_cover_combo"));
      sections = `<div class="meta" style="font-size:11px; margin-top:8px; color:var(--danger);">${esc(t("pack_cant_cover"))} — ${esc(t("pack_ladder_short"))} ${shortHtml}</div>
        <div class="meta" style="font-size:10.5px; margin-top:4px;">${esc(t("pack_cant_cover_hint"))}${limited.length ? ` ${esc(t("pack_limited_tables"))}: ${limited.map(esc).join(", ")}` : ""}</div>`;
    } else {
      plans.push({ key: "fastest", title: t("pack_plan_fastest"), plan: pp.fastest, days: earliest });
      if (targetDays != null) {
        plans.push({ key: "target", title: t("pack_plan_by_target"), plan: pp.byTarget, unreachable: targetDays < earliest });
      }
      // "Cheapest" is bounded to a year after the fastest date - a plan
      // that drags on for years to save a little isn't a useful answer.
      const cheapHorizon = earliest + 365;
      plans.push({ key: "cheapest", title: `${t("pack_plan_cheapest")} (${t("pack_by")} ${fmtDate(cheapHorizon)})`, plan: pp.cheapest });
      // The number shown on the "This page only" switch: by the page's target
      // date when set and reachable, otherwise the cheapest plan.
      const pageBest = (plans.find((c) => c.key === "target" && c.plan) || plans.find((c) => c.key === "cheapest")).plan;
      if (pageBest) pageTotalText = packFmtLocal(Math.ceil(packPlanLocal(pageBest)), currency, true, pageBest.rows[0]?.price);
      {
        // Pick a plan (same plan twice is shown once), then its packs.
        const shown = plans.filter((c) => !plans.some((x) => plans.indexOf(x) < plans.indexOf(c) && x.plan && c.plan && x.plan.total === c.plan.total && x.plan.days === c.plan.days));
        let pick = shown.find((c) => c.key === PACK_PLAN_PICK[calcKey] && c.plan) || shown.find((c) => c.key === "target" && c.plan) || shown.find((c) => c.plan);
        const label = (c) => t(c.key === "fastest" ? "pc_fastest" : c.key === "target" ? "pc_by_target" : "pc_cheapest");
        const packsByDate = (c) => calcKey === "islands" && c && c.key === "fastest";
        const planCard = (c) => {
          if (!c.plan) return `<div class="pc-plan off"><div class="pc-k">${esc(label(c))}</div><small style="color:var(--danger);">${esc(t("pack_not_reachable"))}</small></div>`;
          const late = targetDays != null && c.plan.days > targetDays;
          const d = new Date(today.getTime() + c.plan.days * 86400000);
          let short; try { short = d.toLocaleDateString(LANG === "en" ? undefined : LANG, { day: "numeric", month: "short", timeZone: "UTC" }) + packYearMark(d); } catch (e) { short = fmtDate(c.plan.days); }
          // Islands' Fastest date is when its packs are bought (free income does the rest later).
          const when = c.plan.days === 0 ? t("pack_ready_now") : packsByDate(c) ? t("pca_packs_by").replace("{d}", short) : `${short} · ${c.plan.days}d`;
          return `<button type="button" class="pc-plan${c === pick ? " on" : ""}" data-packpick="${c.key}"><div class="pc-k">${esc(label(c))}</div><b>${String(packFmtLocal(Math.ceil(packPlanLocal(c.plan)), currency, true, c.plan.rows[0]?.price)).replace(/^([\u2066\u200e\u200f]*)([^\d\s\-\u2066-\u2069\u200e\u200f]+)\s?/, '$1<small class="cur">$2</small>')}</b><small style="${late ? "color:var(--danger);" : ""}">${esc(when)}</small>${c === pick && byPack.length ? `<span class="pc-npk">${esc(byPack.length === 1 ? t("pca_pack1") : t("pca_packs").replace("{n}", byPack.length))}</span>` : ""}</button>`;
        };
        const p = pick && pick.plan;
        if (p) pickedTotalText = packFmtLocal(Math.ceil(packPlanLocal(p)), currency, true, p.rows[0]?.price);
        if (PACK_PICK_HOOKS[calcKey]) { const hk = PACK_PICK_HOOKS[calcKey], dd = pick && pick.key === "cheapest" && cheapAt && p === cheapAt.plan ? cheapAt.d : null; setTimeout(() => hk(dd), 0); }
        const byPack = [];
        if (p) p.rows.forEach((r) => {
          let g = byPack.find((x) => x.title === r.title);
          if (!g) { g = { title: r.title, count: 0, subtotal: 0, currency: r.currency, reset: r.reset, resetDay: r.resetDay, cycles: r.cycles, lines: [] }; byPack.push(g); }
          g.count += r.count; g.subtotal += packRowLocal(r); g.sample = g.sample || r.price; g.cycles = Math.max(g.cycles, r.cycles); g.lines.push(r);
        });
        sections = `<div class="pc-plans">${shown.map(planCard).join("")}</div><div class="pc-list"></div>`;
        if (p) {
          aBuilt = true;
          const targetA = `<div class="pca-tg"><span aria-hidden="true">&#127919;</span><span>${esc(t("pca_target"))}</span><input type="date" data-packtarget value="${esc(targetDate)}" aria-label="${esc(t("pack_target_by"))}" />${targetDays != null ? `<span class="${targetDays < 0 ? "bad" : "left"}">${targetDays < 0 ? esc(t("pack_overdue")) : `${targetDays} ${esc(t("pack_days_left"))}`}</span>` : `<span>${esc(t("pack_no_date"))}</span>`}${targetDate ? `<button type="button" class="pca-x" data-packtargetclear title="${esc(t("pack_no_date"))}" aria-label="${esc(t("pack_no_date"))}">&times;</button>` : ""}</div>`;
          const rowsA = pcaRows(byPack, p.rows, packRowLocal, null);
          // Pet Refine: "Buy the marks as Advanced | Common", each side with its own plan's price.
          let marksA = "";
          if (mkTables.length) {
            const as = petMarksBuyAs(), other = as === "adv" ? "common" : "adv";
            let og = null;
            PET_BUYAS_FORCE = other;
            try { og = packGroupsFor(tables, calcKey); } finally { PET_BUYAS_FORCE = null; }
            let op = null;
            try { op = await plannerRun("page", { groups: og, need, calcKey, targetDays }); } catch (e) { op = null; }
            if (stale()) return;
            const oPlan = op ? (pick.key === "fastest" ? op.fastest : pick.key === "target" ? op.byTarget : op.cheapest) : null;
            const priceOf = (pl) => (pl ? packFmtLocal(Math.ceil(packPlanLocal(pl)), currency, true, pl.rows[0]?.price) : "\u2014");
            const pr = { [as]: priceOf(p), [other]: priceOf(oPlan) };
            const same = oPlan && Math.ceil(packPlanLocal(oPlan)) === Math.ceil(packPlanLocal(p));
            // "1 Advanced = 8 Common in this pack (2 or 16, 4 or 32 … 40 or 320)", from the pack's own rows.
            let sameHtml = "";
            if (same) {
              const tb = mkTables[0], cols = packEffectiveCols(tb), lk = packLinkFor(tb.id);
              const ci = (nm) => Number(Object.keys(cols).find((k) => cols[k] === nm));
              const ca = ci("Advanced Marks"), cc = ci("Common Marks");
              const pairs = (tb.rows || []).map((r) => r.cells || []).filter((c) => packParseNum(c[lk.priceCol]) > 0).map((c) => [packParseNum(c[ca]) * packColMultiplier(lk, ca), packParseNum(c[cc]) * packColMultiplier(lk, cc)]).filter(([a, c]) => a > 0 && c > 0);
              const txt = pairs.map(([a, c]) => t("pca_mk_or").replace("{a}", qty(a)).replace("{c}", qty(c)));
              const list = txt.length > 3 ? `${txt.slice(0, 2).join(", ")} \u2026 ${txt[txt.length - 1]}` : txt.join(", ");
              const ratio = pairs.length ? Math.round(pairs[0][1] / pairs[0][0]) : ADVANCED_MARK_VALUE;
              sameHtml = `<div class="pca-note ok">&#10003; ${esc(t("pca_mk_same").replace("{n}", ratio).replace("{list}", list))}</div>`;
            }
            const btn = (k, item, lbl) => `<button type="button" data-pcamarks="${k}" class="${as === k ? "active" : ""}" aria-pressed="${as === k}">${pcaIcon(item)}<span>${esc(t(lbl))} &middot; ${esc(pr[k])}</span></button>`;
            marksA = `<div class="pca-mk"><div class="pca-mk-t">${esc(t("pca_mk_buy_as"))}</div><div class="seg pca-mk-seg">${btn("adv", "Advanced Marks", "pca_mk_adv")}${btn("common", "Common Marks", "pca_mk_com")}</div>${sameHtml}</div>`;
          }
          const tradesA = tradesCard(p.trades);
          // Free day bonus (Shining City Pack's first buy of each event day): not a pack row.
          const bonusA = Object.entries(p.bonus || {}).map(([n, v]) => `<div class="pca-bonus">${pcaIcon(n)}<span>${esc(t("pca_day_bonus").replace("{q}", (Number(ISL_RULES.tomeFreeDay) || 0).toLocaleString()).replace("{n}", qty(v)))}</span></div>`).join("");
          sections = `<div class="pc-plans">${shown.map(planCard).join("")}</div>${marksA}${targetA}<div class="pc-list">${tradesA}<div class="pca-h">${esc(t("pca_buy"))}</div>${rowsA}${bonusA}${islCopiesLine(p)}${islCheckedHtml(p.rows)}@@PCFREE@@</div>`;
        }
      }
    }
  }

  // View switch: "Shared with Budgets" (this page's share of the combined
  // plan) or "This page only" (plan as if nothing else were being worked on).
  const canShare = !!sharedSections || !!(shared && shared.lazyShare);
  if (canShare && !PACK_COST_VIEW[calcKey]) PACK_COST_VIEW[calcKey] = packCostDefaultView();
  const usingShared = !!sharedSections && PACK_COST_VIEW[calcKey] === "shared";
  const known = (PACK_VIEW_TOTALS[calcKey] && PACK_VIEW_TOTALS[calcKey].sig === viewSig) ? PACK_VIEW_TOTALS[calcKey] : { sig: viewSig };
  if (sharedTotalText) known.shared = sharedTotalText; else sharedTotalText = known.shared || "";
  if (pageTotalText) known.page = pageTotalText; else pageTotalText = known.page || "";
  PACK_VIEW_TOTALS[calcKey] = known;
  if (stale()) return;
  packCostShown(calcKey, (usingShared ? sharedTotalText : (pickedTotalText || pageTotalText)) || null);
  if (usingShared) sections = sharedSections;
  let fallbackNote = "";
  if (shared && !canShare && !shared.lazyShare && PACK_COST_MODE === "still") {
    if (shared.notIncluded) fallbackNote = sharedNote(t("combined_not_included"));
    else if (shared.combined && Object.keys(need).length && (!shared.combined.chosen || !shared.included)) fallbackNote = sharedNote(t("combined_cant"));
  }
  // "Already counted": the running cards only (every trade has its own row in the list).
  const freeBits = activeCards.used.map((u) => `${u.title}${u.until ? ` (${t("pk_active_until")} ${u.until.toLocaleDateString(LANG === "en" ? undefined : LANG, { day: "numeric", month: "short", timeZone: "UTC" })})` : ""}`);
  let freeHtml = freeBits.length ? `<details class="pc-free"><summary>&#10003; ${esc(t("pc_cards_count").replace("{c}", activeCards.used.length))}</summary><div>${freeBits.map((b) => `<div>${esc(b)}</div>`).join("")}</div></details>` : "";
  // (No plan list drawn, e.g. packs can't cover it: the free trades still get their rows.)
  if (freeParts.length && !/pca-tc/.test(sections)) freeHtml += `<div class="pc-list">${tradesCard([])}</div>`;
  containerEl.style.minHeight = "";
  containerEl.innerHTML = `
    <div class="pc-card pca">
      ${head}
      ${usingShared || (aBuilt && !usingShared) ? "" : targetHtml}
      ${fallbackNote}
      ${uncoveredHtml}
      ${aBuilt && !usingShared ? "" : freeHtml}
      <div class="pc-sec">${aBuilt && !usingShared ? sections.replace("@@PCFREE@@", freeHtml) : sections}</div>
      ${canShare ? `<div class="pc-view pca-scope"><div class="seg" data-packview><button type="button" data-packviewbtn="page" class="${usingShared ? "" : "active"}">${esc(t("pca_only").replace("{page}", packPageLabel(calcKey)))}</button><button type="button" data-packviewbtn="shared" class="${usingShared ? "active" : ""}">${esc(t("pca_with_others"))}</button></div></div>` : ""}
    </div>`;
  containerEl.querySelectorAll("[data-packviewbtn]").forEach((b) => b.addEventListener("click", () => { PACK_COST_VIEW[calcKey] = b.dataset.packviewbtn; rerender(); }));
  containerEl.querySelectorAll("[data-packpick]").forEach((b) => b.addEventListener("click", () => { PACK_PLAN_PICK[calcKey] = b.dataset.packpick; rerender(); }));
  containerEl.querySelectorAll("[data-pcamarks]").forEach((b) => b.addEventListener("click", async () => {
    const st = await ensurePetMarksState();
    if (st.buyAs === b.dataset.pcamarks) return;
    st.buyAs = b.dataset.pcamarks === "common" ? "common" : "adv";
    saveCalcState("pet_refine_marks", st);
    PACK_PLAN_CACHE.clear();
    budgetInvalidate();
    rerender();
  }));
  const toBudgets = containerEl.querySelector("[data-gotobudgets]");
  if (toBudgets) toBudgets.addEventListener("click", () => { const b = document.querySelector('.topnav-groups [data-tab="budgets"]'); if (b) b.click(); });
  containerEl.querySelector("[data-packtoggle]").addEventListener("click", () => { PACK_COST_OPEN[calcKey] = false; rerender(); });
  const dateEl = containerEl.querySelector("[data-packtarget]");
  if (dateEl) dateEl.addEventListener("change", async () => {
    PACK_TARGET_CACHE[calcKey] = dateEl.value || "";
    saveCalcState(`pack_target_${calcKey}`, { date: PACK_TARGET_CACHE[calcKey] });
    rerender();
    if (PACK_TARGET_HOOKS[calcKey]) PACK_TARGET_HOOKS[calcKey]();
  });
  const clearEl = containerEl.querySelector("[data-packtargetclear]");
  if (clearEl) clearEl.addEventListener("click", async () => {
    PACK_TARGET_CACHE[calcKey] = "";
    saveCalcState(`pack_target_${calcKey}`, { date: "" });
    rerender();
    if (PACK_TARGET_HOOKS[calcKey]) PACK_TARGET_HOOKS[calcKey]();
  });
}
// ---- Currency conversion ----
// Rates are "units per 1 USD", editable in Admin -> Currencies (site_config
// "currency_rates"); these built-in values are only the starting point.
const CURRENCY_DEFAULT_RATES = { USD: 1, EUR: 0.92, GBP: 0.79, SAR: 3.75, AED: 3.67, QAR: 3.64, KWD: 0.31, BHD: 0.376, OMR: 0.385, EGP: 48.5, TRY: 34, INR: 84, JPY: 150, CNY: 7.2, KRW: 1380, CAD: 1.37, AUD: 1.52, BRL: 5.5, RUB: 92, PHP: 57, IDR: 15800, MYR: 4.4 };
function currencyRates() {
  const saved = siteConfig("currency_rates", null);
  const out = { ...CURRENCY_DEFAULT_RATES };
  if (saved && typeof saved === "object") Object.keys(saved).forEach((k) => { const v = Number(saved[k]); if (v > 0) out[k] = v; });
  return out;
}
// Every viewer picks their own display currency (kept in this browser).
let DISPLAY_CURRENCY = (() => { try { return localStorage.getItem("display_currency") || ""; } catch (e) { return ""; } })();
function setDisplayCurrency(code) {
  DISPLAY_CURRENCY = code || "";
  try { localStorage.setItem("display_currency", DISPLAY_CURRENCY); } catch (e) {}
}
// Store price slots: the real in-store price of each USD price point per
// currency (Admin -> Currencies, site_config "currency_prices"). Stores add
// tax or round differently, so a $4.99 pack is rarely exactly 4.99 x rate.
// A slot that is filled wins over the rate; an empty slot falls back to it.
const CURRENCY_PRICE_SLOTS = ["0.99", "1.99", "2.99", "4.99", "9.99", "19.99", "49.99", "99.99"];
function currencyPrices() {
  const saved = siteConfig("currency_prices", null);
  return saved && typeof saved === "object" ? saved : {};
}
// Built-in price points plus the ones added in Admin (site_config
// "currency_slots"), sorted by value.
function currencyPriceSlots() {
  // Set from the Packs page (or Admin): the full, editable list wins.
  const list = siteConfig("pack_price_points", null);
  if (Array.isArray(list)) return [...new Set(list.map((x) => Number(x)).filter((n) => n > 0).map((n) => n.toFixed(2)))].sort((a, b) => Number(a) - Number(b));
  const extra = siteConfig("currency_slots", null);
  const all = new Set(CURRENCY_PRICE_SLOTS);
  if (Array.isArray(extra)) extra.forEach((x) => { const n = Number(x); if (n > 0) all.add(n.toFixed(2)); });
  return [...all].sort((a, b) => Number(a) - Number(b));
}
function currencySlotPrice(usd, code) {
  const slots = currencyPrices()[code];
  if (!slots) return null;
  const key = Object.keys(slots).find((s) => Math.abs(Number(s) - usd) < 0.005);
  if (!key) return null;
  const v = Number(slots[key]);
  return v > 0 ? v : null;
}
// Price points are saved as a full list; renaming or removing one moves or
// drops its store prices too, so nothing is left pointing at an old value.
async function savePackPricePoints(list, renameFrom, renameTo) {
  const prices = JSON.parse(JSON.stringify(currencyPrices()));
  Object.keys(prices).forEach((code) => {
    const slots = prices[code] || {};
    if (renameFrom != null && slots[renameFrom] != null) { if (renameTo) slots[renameTo] = slots[renameFrom]; delete slots[renameFrom]; }
    Object.keys(slots).forEach((k) => { if (!list.includes(k)) delete slots[k]; });
    if (!Object.keys(slots).length) delete prices[code];
  });
  await saveSiteConfig("pack_price_points", list);
  await saveSiteConfig("currency_prices", prices);
}
// Each viewer's own store prices ({ SAR: { "4.99": 18.99 } }), typed on the
