    const ids = flat.map((c) => `${c.piece.key}|${c.slot}`);
    const of = (id) => { const [k, sl] = id.split("|"); return { c: flat.find((x) => x.piece.key === k && x.slot === Number(sl)), st: CHARM_CALC_STATE[k][Number(sl)] }; };
