    allMax: () => { const cap = charmCapIdx(); return CHARM_PIECES.every((p) => CHARM_CALC_STATE[p.key].every((st) => CHARM_LEVELS.indexOf(String(st.current)) >= cap)); },
    snap: () => CHARM_CALC_STATE,
    max: () => { const cap = charmCapIdx(); CHARM_PIECES.forEach((p) => CHARM_CALC_STATE[p.key].forEach((st) => { const v = CHARM_LEVELS.indexOf(String(st.current)) >= cap ? st.current : CHARM_LEVELS[cap]; st.current = v; st.target = v; })); },
    reset: (kept) => { CHARM_PIECES.forEach((p) => CHARM_CALC_STATE[p.key].forEach((st, i) => { const v = kept && kept[p.key] && kept[p.key][i]; if (v) { st.current = v.current; st.target = v.target; } })); },
    save: () => saveCalcState("charm", CHARM_CALC_STATE),
    after: () => { renderTroopSections(); updateCharmTotals(); },
