  skill: "expert_skill_nodes?select=id,expert,skill,level,exp_cost,book_cost,stat_type,stat_value&order=sort_order",
  research: "expert_research_nodes?select=id,expert,path_number,path_name,level,stat_type,stat_value,sigil_cost,sigil_per_level,stat_type2,stat_value2&order=sort_order",
