const EXPERT_INVENTORY_BASE_FIELDS = [
  "Sail of Conquest", "Fiery Heart", "Compass", "Books of Knowledge",
  "Expert Speedups (minutes)", "General Sigils",
];
// Backpack fields = the base items + one "<Expert> Sigils" box per expert
// in the roster (so a newly added expert gets its own sigils automatically).
function expertInventoryFields() {
  // Per-expert sigils moved onto each expert's card; Backpack keeps only what
  // is shared across experts, plus a read-only summary of the per-expert ones.
  return EXPERT_INVENTORY_BASE_FIELDS.slice();
}
// Affinity you own = the gift items you hold (plus any Affinity number
